import type { SubjectBank } from '@/types';

export const combinedScienceBank: SubjectBank = {
  short: [
    // --- EXISTING 20 SHORT QUESTIONS (kept unchanged) ---
    { question: "[Biology] State the equation for photosynthesis.", answer: "Carbon dioxide + water → glucose + oxygen (6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂). Light energy is absorbed by chlorophyll in the chloroplasts.", acceptedAnswers: ["6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂", "CO2 + water → glucose + oxygen using light energy", "Carbon dioxide and water produce glucose and oxygen in the presence of light", "Light energy converts CO2 and water into glucose and oxygen"], marks: 2, hint: "Light energy is used by chlorophyll; the products are glucose and oxygen" },
    { question: "[Physics] What is the difference between speed and velocity?", answer: "Speed is a scalar quantity — it only has magnitude (e.g. 30 m/s). Velocity is a vector quantity — it has both magnitude and direction (e.g. 30 m/s north). An object moving in a circle at constant speed has changing velocity because its direction changes.", acceptedAnswers: ["Speed has magnitude only; velocity has magnitude and direction", "Speed is scalar, velocity is vector", "Velocity includes direction, speed does not", "Speed tells you how fast; velocity tells you how fast and in which direction"], marks: 2, hint: "One has direction, the other does not — vector vs scalar" },
    { question: "[Chemistry] What type of bonding exists in water (H₂O)? Explain briefly.", answer: "Covalent bonding. The oxygen atom shares one pair of electrons with each hydrogen atom, forming two covalent bonds. Water is a simple molecular substance with strong covalent bonds within molecules but weak intermolecular forces between molecules.", acceptedAnswers: ["Covalent bonding — shared electrons between oxygen and hydrogen", "Water has covalent bonds formed by electron sharing", "H2O has two covalent bonds where electrons are shared", "Covalent — non-metals share electrons rather than transfer them"], marks: 2, hint: "Water is made of non-metals — do they share or transfer electrons?" },
    { question: "[Biology] Name the four components of blood and state the function of each.", answer: "Red blood cells: carry oxygen (using haemoglobin). White blood cells: fight infection (phagocytes engulf pathogens; lymphocytes produce antibodies). Platelets: help form blood clots at wound sites. Plasma: liquid component that transports dissolved substances (glucose, hormones, CO₂, urea, proteins).", acceptedAnswers: ["RBCs carry oxygen; WBCs fight infection; platelets clot blood; plasma transports substances", "Red cells (haemoglobin/oxygen), white cells (immunity), platelets (clotting), plasma (transport)", "Erythrocytes carry O2; leucocytes fight disease; thrombocytes clot; plasma is the liquid transport medium", "Four components: oxygen-carrying red cells, infection-fighting white cells, clotting platelets, and liquid plasma"], marks: 4, hint: "Three cell types and one liquid — what does each do?" },
    { question: "[Chemistry] What is an ion? Distinguish between a cation and an anion.", answer: "An ion is an atom or group of atoms that has gained or lost electrons, giving it a net electrical charge. A cation is positively charged — it has lost electrons (e.g. Na⁺). An anion is negatively charged — it has gained electrons (e.g. Cl⁻). Metals typically form cations; non-metals typically form anions.", acceptedAnswers: ["Ion = charged atom; cation = positive (lost electrons); anion = negative (gained electrons)", "Ions are charged particles; cations lost electrons and are positive; anions gained electrons and are negative", "A cation has fewer electrons than protons; an anion has more electrons than protons", "Ions form when atoms lose or gain electrons — positive ions are cations, negative are anions"], marks: 2, hint: "Cations are positive (lost electrons); anions are negative (gained electrons)" },
    { question: "[Biology] What is osmosis? Explain the direction water moves.", answer: "Osmosis is the net movement of water molecules through a partially permeable membrane from a region of higher water concentration (more dilute solution) to a region of lower water concentration (more concentrated solution). Water moves down its concentration gradient. This is a passive process — no energy is required.", acceptedAnswers: ["Osmosis is water moving through a partially permeable membrane from dilute to concentrated solution", "Water diffuses across a semipermeable membrane from high to low water concentration", "Net movement of water molecules down a concentration gradient through a partially permeable membrane", "Passive movement of water from dilute to more concentrated solution through a selectively permeable membrane"], marks: 2, hint: "It's water movement through a membrane — which way does water move? From dilute to concentrated or vice versa?" },
    { question: "[Physics] State Newton's First Law of Motion.", answer: "An object remains at rest or continues to move at a constant velocity (constant speed in a straight line) unless acted upon by a resultant (unbalanced) force. This is the principle of inertia: objects resist changes to their state of motion.", acceptedAnswers: ["An object stays still or moves at constant velocity unless a resultant force acts on it", "Objects resist changes in their motion — they need an unbalanced force to accelerate or stop", "A body continues at rest or uniform velocity unless acted on by a net force", "Without a resultant force an object remains at rest or moves at constant speed in a straight line"], marks: 2, hint: "What happens when there is no net force acting on an object?" },
    { question: "[Chemistry] What is the difference between an exothermic and an endothermic reaction?", answer: "An exothermic reaction releases energy to the surroundings, causing the temperature of the surroundings to increase. Products have less energy than reactants. Examples: combustion, neutralisation. An endothermic reaction absorbs energy from the surroundings, causing the temperature of the surroundings to decrease. Products have more energy than reactants. Example: thermal decomposition.", acceptedAnswers: ["Exothermic releases heat (temperature rises); endothermic absorbs heat (temperature falls)", "Exothermic: energy is released, surroundings get warmer. Endothermic: energy is absorbed, surroundings get cooler", "In exothermic reactions energy is given out; in endothermic energy is taken in from surroundings", "Exothermic = products have less energy than reactants; endothermic = products have more energy"], marks: 2, hint: "Exo = exit (heat leaves to surroundings). Endo = enter (heat enters from surroundings)." },
    { question: "[Biology] Define 'active transport' and explain how it differs from diffusion.", answer: "Active transport is the movement of molecules or ions across a cell membrane against a concentration gradient (from low to high concentration), using energy (ATP) from respiration. This is different from diffusion, which is passive (requires no energy) and moves particles down a concentration gradient (from high to low concentration). Example: root hair cells absorbing mineral ions from the soil.", acceptedAnswers: ["Active transport moves substances against the concentration gradient using ATP; diffusion is passive and moves down the gradient", "Active transport requires energy and goes from low to high concentration; diffusion needs no energy and goes high to low", "Active transport uses ATP to move substances up a concentration gradient, unlike passive diffusion", "The key difference is energy use — active transport requires respiration-derived energy; diffusion does not"], marks: 2, hint: "Is it going up or down the concentration gradient? Does it need energy?" },
    { question: "[Physics] State the equation for wave speed, defining each term.", answer: "Wave speed (v) = frequency (f) × wavelength (λ). v is in m/s. f is in Hz (hertz) — the number of complete waves per second. λ (lambda) is in metres — the distance from one point on a wave to the same point on the next wave.", acceptedAnswers: ["v = f × λ where v is wave speed (m/s), f is frequency (Hz), and λ is wavelength (m)", "Wave speed equals frequency multiplied by wavelength", "Speed = frequency × wavelength; measured in m/s, Hz, and metres respectively", "v = fλ — speed in m/s, frequency in hertz, wavelength in metres"], marks: 2, hint: "v = f × λ. Make sure you know the units for each quantity." },
    { question: "[Chemistry] What is meant by the 'reactivity series' of metals?", answer: "The reactivity series is a list of metals ordered from most reactive (top) to least reactive (bottom) based on how readily they react with water, acids, and oxygen. More reactive metals displace less reactive metals from their compounds. Order (most to least reactive): potassium, sodium, calcium, magnesium, aluminium, zinc, iron, copper, silver, gold.", acceptedAnswers: ["A list ranking metals from most to least reactive based on their reactions with water and acids", "The reactivity series orders metals by how vigorously they react — potassium most reactive, gold least", "A league table of metals by reactivity — more reactive metals displace less reactive ones from compounds", "Metals ranked by reactivity: K, Na, Ca, Mg, Al, Zn, Fe, Cu, Ag, Au from most to least reactive"], marks: 2, hint: "Think about which metals react vigorously with water (e.g. sodium) vs. which barely react at all (e.g. gold)" },
    { question: "[Biology] What is the difference between aerobic and anaerobic respiration? State the word equations for each.", answer: "Aerobic (with oxygen): glucose + oxygen → carbon dioxide + water. Produces a large amount of ATP. Occurs in mitochondria. Anaerobic (without oxygen): in humans: glucose → lactic acid (produces small amount of ATP, causes muscle fatigue). In yeast: glucose → ethanol + carbon dioxide (fermentation). Anaerobic is faster but much less efficient.", acceptedAnswers: ["Aerobic: glucose + O2 → CO2 + water (lots of ATP). Anaerobic in humans: glucose → lactic acid (less ATP)", "Aerobic uses oxygen and produces CO2 + water; anaerobic lacks oxygen and produces lactic acid (humans) or ethanol + CO2 (yeast)", "Aerobic respiration produces much more energy than anaerobic; anaerobic produces lactic acid or ethanol as byproducts", "Aerobic = with oxygen, efficient, CO2 and water. Anaerobic = without oxygen, inefficient, lactic acid or fermentation products"], marks: 3, hint: "State both equations, compare energy released, note where each occurs" },
    { question: "[Physics] What is the difference between mass and weight?", answer: "Mass is the amount of matter in an object, measured in kilograms (kg). It is a scalar quantity and does not change with location. Weight is the gravitational force acting on a mass, measured in newtons (N). Weight = mass × gravitational field strength (W = mg). On Earth, g ≈ 10 N/kg; on the Moon, g ≈ 1.6 N/kg, so weight is less but mass is the same.", acceptedAnswers: ["Mass is the amount of matter (kg) and doesn't change; weight is the gravitational force (N) which varies by location", "Mass is measured in kg and stays constant; weight = mg and changes on other planets", "Mass is a scalar (kg); weight is a force (N) = mass × g, so changes with gravitational field strength", "Weight changes with gravity; mass does not — W = mg links them"], marks: 2, hint: "Mass is 'how much stuff'. Weight is the force gravity pulls with. Which changes on the Moon?" },
    { question: "[Chemistry] Describe what collision theory says about rates of reaction.", answer: "Collision theory states that for a reaction to occur, particles must collide with sufficient energy (at least equal to the activation energy) and the correct orientation. Rate of reaction increases when: temperature increases (more particles have energy ≥ activation energy, and particles move faster so collide more frequently); concentration increases (more particles in the same volume, so more frequent collisions); surface area increases (more particles exposed to collisions); a catalyst is added (lowers the activation energy needed).", acceptedAnswers: ["Particles must collide with enough energy (activation energy) and correct orientation for a reaction to occur", "Reaction rate increases with temperature, concentration, surface area, or a catalyst because collisions become more frequent or more energetic", "Collision theory: successful collisions require sufficient energy and correct orientation; rate increases when either factor improves", "For a reaction: particles must meet, have energy ≥ activation energy, and align correctly — temperature/concentration/SA/catalyst all increase collision frequency or energy"], marks: 3, hint: "What two things must be true for a collision to result in a reaction? What factors change collision frequency or energy?" },
    { question: "[Biology] State three symptoms of Type 2 diabetes and explain the underlying cause.", answer: "Symptoms include: excessive thirst (polydipsia), frequent urination (polyuria), fatigue, blurred vision. Cause: the body's cells become resistant to insulin, or the pancreas does not produce enough insulin. As a result, blood glucose levels remain high after eating (hyperglycaemia). Unlike Type 1, Type 2 is strongly associated with lifestyle factors (obesity, lack of exercise, poor diet), though genetic factors also play a role.", acceptedAnswers: ["Symptoms: thirst, frequent urination, fatigue. Cause: cells are resistant to insulin so blood glucose remains high", "Type 2: insulin resistance or insufficient insulin production → hyperglycaemia. Symptoms include thirst, tiredness, blurred vision", "Body does not respond to insulin properly, keeping blood sugar high; symptoms are excessive thirst, frequent urination, and fatigue", "Cause is insulin resistance or low insulin production; key symptoms are polydipsia, polyuria, and fatigue"], marks: 3, hint: "What hormone controls blood glucose? What happens when the body stops responding to it?" },
    { question: "[Physics] What is specific heat capacity? State the equation.", answer: "Specific heat capacity (c) is the energy required to raise the temperature of 1 kg of a substance by 1°C (or 1 K). Equation: E = mcΔT, where E = energy transferred (J), m = mass (kg), c = specific heat capacity (J/kg/°C), ΔT = temperature change (°C). Water has a high specific heat capacity (4,200 J/kg/°C), which is why it is used as a coolant.", acceptedAnswers: ["E = mcΔT; c is energy needed per kg per degree; water's SHC is 4200 J/kg/°C", "Specific heat capacity is how much energy is needed to raise 1 kg by 1°C; equation: E = mcΔT", "SHC = energy per kg per °C change; E = m × c × ΔT", "The energy needed to heat 1 kg of a substance by 1 degree; E = mcΔT where ΔT is temperature change"], marks: 2, hint: "E = mcΔT. What does each symbol mean? What are the units?" },
    // --- EXISTING SHORT (Biology type 2 diabetes was already #15, aerobic was already #12) ---
    // The 4 below were originally in the 'mid' section but presented as 3-mark items:
    { question: "[Biology] Name the four main types of pathogen and give one example of each.", answer: "Bacteria (e.g. Salmonella, causing food poisoning). Viruses (e.g. influenza virus, causing flu). Fungi (e.g. Athlete's foot fungus). Protists (e.g. Plasmodium, causing malaria — spread by mosquitoes). Bacteria and fungi are living cells; viruses are not — they require a host cell to replicate.", acceptedAnswers: ["Bacteria (Salmonella), viruses (influenza), fungi (athlete's foot), protists (Plasmodium)", "The four pathogen types are bacteria, viruses, fungi, and protists — each causes disease differently", "Bacteria, viruses, fungi, protists; examples include Salmonella, flu virus, athlete's foot, and malaria parasite", "Pathogen types: bacterial (e.g. TB), viral (e.g. HIV), fungal (e.g. rose black spot), protist (e.g. malaria)"], marks: 2, hint: "There are four types — think BVFP. Give one example disease for each." },
    { question: "[Chemistry] State the difference between a compound and a mixture.", answer: "A compound is a substance containing two or more elements chemically bonded together in a fixed ratio. It has different properties from its elements and can only be separated by chemical reactions. A mixture contains two or more substances that are not chemically combined — they can be separated by physical means (filtration, distillation, chromatography) and retain their individual properties.", acceptedAnswers: ["Compound: elements chemically bonded, fixed ratio, different properties. Mixture: substances not chemically combined, separable physically", "Compounds have elements in fixed ratios joined by chemical bonds; mixtures have variable composition and can be physically separated", "In a compound atoms are chemically joined; in a mixture substances are physically mixed and keep their own properties", "Compound = chemical bonds, fixed proportions. Mixture = no bonding, variable composition, separable"], marks: 2, hint: "Key difference: are the elements chemically bonded or just physically mixed?" },
    { question: "[Physics] State Ohm's Law and give the equation.", answer: "Ohm's Law states that the current through a conductor is directly proportional to the potential difference across it, provided the temperature remains constant. Equation: V = IR, where V = voltage/potential difference (volts, V), I = current (amperes, A), R = resistance (ohms, Ω).", acceptedAnswers: ["V = IR; current is proportional to voltage at constant temperature", "Ohm's Law: V = IR where voltage = current × resistance, provided temperature is constant", "At constant temperature, V ∝ I; the constant of proportionality is resistance R; equation V = IR", "Current is proportional to pd at constant temperature; V = IR"], marks: 2, hint: "V = IR. What three quantities does it link? What condition must be constant?" },
    { question: "[Biology] What is mitosis? State why it is important.", answer: "Mitosis is a type of cell division where one parent cell divides to produce two genetically identical daughter cells, each with the same number of chromosomes as the parent cell (diploid). It is used for growth, repair of damaged tissues, and asexual reproduction. The daughter cells are clones — they have identical DNA to the parent cell.", acceptedAnswers: ["Mitosis produces two genetically identical diploid cells; used for growth and repair", "Cell division producing two identical daughter cells with the same chromosome number as the parent; important for growth and tissue repair", "Mitosis: one cell → two identical cells (same DNA, same chromosome number); used in growth, repair, and asexual reproduction", "Mitosis produces clones — genetically identical cells — used for body growth and replacing damaged cells"], marks: 2, hint: "How many daughter cells? Are they identical or different? When does the body use mitosis?" },
    // --- NEW SHORT QUESTIONS ---
    // Biology - Cell Biology
    { question: "[Biology] State three differences between a plant cell and an animal cell.", answer: "Plant cells have: (1) a cell wall made of cellulose (animal cells do not); (2) a large permanent vacuole (animal cells may have small temporary vacuoles); (3) chloroplasts for photosynthesis (animal cells have none). Both have a cell membrane, nucleus, cytoplasm, mitochondria, and ribosomes.", acceptedAnswers: ["Plant cells have cell wall, large vacuole, and chloroplasts; animal cells lack all three", "Cell wall, permanent vacuole, chloroplasts — all present in plants but absent in animals", "Plants: cellulose cell wall, chloroplasts, large central vacuole. Animals: none of these structures", "Three differences: cell wall (plant only), chloroplasts (plant only), large vacuole (plant only)"], marks: 2, hint: "Think about what plant cells have that animal cells do not — three key structures." },
    { question: "[Biology] Define diffusion and give one example in the human body.", answer: "Diffusion is the net movement of particles (molecules or ions) from an area of high concentration to an area of low concentration, down a concentration gradient. It is a passive process — no energy is needed. Example: oxygen diffuses from the alveoli (high concentration) into the blood capillaries (low concentration) during gas exchange in the lungs.", acceptedAnswers: ["Diffusion = net movement of particles from high to low concentration; e.g. oxygen from alveoli to blood", "Passive movement down a concentration gradient; example: CO2 diffusing from respiring cells into the blood", "Net movement of molecules from high to low concentration without energy; e.g. glucose from gut into blood", "Diffusion: particles spread from high to low concentration; example: oxygen entering blood in the alveoli"], marks: 2, hint: "High to low concentration, no energy needed. Name any example from the lungs, gut, or cells." },
    { question: "[Biology] What are stem cells? Distinguish between embryonic and adult stem cells.", answer: "Stem cells are undifferentiated cells that can divide and develop into different specialised cell types. Embryonic stem cells can differentiate into any cell type in the body (pluripotent) — they are found in early embryos. Adult stem cells are found in specific tissues (e.g. bone marrow) and can only differentiate into a limited range of cell types (multipotent) — for example, producing red and white blood cells.", acceptedAnswers: ["Stem cells are undifferentiated and can become specialised; embryonic = pluripotent (any cell); adult = limited range", "Undifferentiated cells that can differentiate; embryonic stem cells can form any cell type; adult stem cells are more restricted", "Embryonic stem cells are pluripotent (any cell type); adult stem cells are multipotent (limited types); both are undifferentiated", "Stem cells can divide and differentiate; embryonic ones are more versatile than adult stem cells found in bone marrow"], marks: 2, hint: "Both are undifferentiated. The key difference is how many cell types each can become." },
    // Biology - Organisation
    { question: "[Biology] Name the four chambers of the heart and describe the direction of blood flow.", answer: "The four chambers are: right atrium, right ventricle, left atrium, left ventricle. Blood flow: deoxygenated blood enters the right atrium → right ventricle → pulmonary artery → lungs. Oxygenated blood returns from lungs → left atrium → left ventricle → aorta → body.", acceptedAnswers: ["Right atrium → right ventricle → lungs; left atrium → left ventricle → body", "Four chambers: right atrium, right ventricle, left atrium, left ventricle; right side pumps to lungs, left to body", "RA → RV → pulmonary artery → lungs → LA → LV → aorta → body", "Right side receives deoxygenated blood and pumps to lungs; left side receives oxygenated blood and pumps to body"], marks: 2, hint: "Right side = pulmonary circuit (lungs). Left side = systemic circuit (body). Trace the path." },
    { question: "[Biology] What is the role of villi in the small intestine?", answer: "Villi are finger-like projections lining the small intestine that massively increase the surface area for absorption of digested food molecules. Each villus has a thin wall (one cell thick), a rich network of blood capillaries (absorb glucose and amino acids), and a lacteal (lymph vessel, absorbs fatty acids and glycerol). Together these features allow rapid and efficient absorption of nutrients into the bloodstream.", acceptedAnswers: ["Villi increase surface area for absorption; thin walls and good blood supply allow rapid uptake of glucose and amino acids", "Villi provide large surface area, thin walls, and rich blood supply to absorb digested food efficiently", "Finger-like projections increase surface area; capillaries absorb glucose/amino acids; lacteals absorb fats", "Villi maximise absorption of nutrients from the small intestine into the blood through increased surface area and thin walls"], marks: 2, hint: "Three adaptations: surface area, wall thickness, blood supply. What's the purpose of each?" },
    // Biology - Infection and Response
    { question: "[Biology] What is the difference between a vaccine and an antibiotic?", answer: "A vaccine contains dead, weakened, or fragments of a pathogen (or antigens). When injected, it stimulates the immune system to produce antibodies and memory lymphocytes without causing disease. If the real pathogen is encountered later, the immune response is rapid and prevents illness. An antibiotic is a medicine that kills or inhibits the growth of bacteria inside the body. Antibiotics do not work against viruses.", acceptedAnswers: ["Vaccines prevent infection by stimulating immunity; antibiotics treat bacterial infections after they occur; antibiotics don't work on viruses", "A vaccine triggers the immune system to make memory cells; an antibiotic kills bacteria; antibiotics are ineffective against viruses", "Vaccines give immunity without illness by stimulating antibody production; antibiotics destroy bacteria but cannot kill viruses", "Vaccine = preventative, uses antigens to create memory. Antibiotic = curative, kills bacteria only"], marks: 2, hint: "One prevents disease (vaccine), the other treats bacterial infections (antibiotic). What is the key limitation of antibiotics?" },
    // Biology - Bioenergetics
    { question: "[Biology] State three limiting factors for photosynthesis.", answer: "The three main limiting factors are: (1) Light intensity — increasing light increases rate until another factor limits. (2) Carbon dioxide concentration — more CO₂ speeds up the dark reactions. (3) Temperature — higher temperature speeds up enzyme activity up to an optimum, beyond which enzymes denature. Any one of these factors can be the limiting factor — the factor in shortest supply prevents the rate from increasing further.", acceptedAnswers: ["Light intensity, CO2 concentration, and temperature are the three limiting factors", "The rate of photosynthesis is limited by light, CO2 levels, and temperature", "Three factors: light intensity, carbon dioxide concentration, and temperature — whichever is lowest limits the rate", "Limiting factors: light, CO2, temperature (water availability is sometimes included as a fourth)"], marks: 2, hint: "Which three environmental variables control how fast a plant can photosynthesise?" },
    // Biology - Homeostasis
    { question: "[Biology] Describe the role of the pancreas in blood glucose regulation.", answer: "The pancreas monitors blood glucose concentration. When blood glucose is too high (after eating): beta cells in the islets of Langerhans secrete insulin. Insulin causes liver and muscle cells to take up glucose and convert it to glycogen (glycogenesis), lowering blood glucose. When blood glucose is too low (after exercise or fasting): alpha cells secrete glucagon. Glucagon causes the liver to break down glycogen back into glucose (glycogenolysis), raising blood glucose.", acceptedAnswers: ["Pancreas releases insulin when blood glucose is high (converts glucose to glycogen); releases glucagon when low (converts glycogen back to glucose)", "High blood glucose → insulin from pancreas → glycogen stored; low blood glucose → glucagon → glycogen converted back to glucose", "Insulin lowers blood glucose by promoting glycogen storage; glucagon raises it by promoting glycogen breakdown; both from the pancreas", "Beta cells make insulin (lowers glucose); alpha cells make glucagon (raises glucose); negative feedback maintains normal levels"], marks: 2, hint: "Two hormones: insulin (lowers glucose) and glucagon (raises glucose). Which cells make each?" },
    // Biology - Inheritance
    { question: "[Biology] What is the difference between dominant and recessive alleles?", answer: "An allele is a version of a gene. A dominant allele is always expressed in the phenotype — even if only one copy is present (heterozygous). A recessive allele is only expressed if two copies are present (homozygous recessive). If an organism has one dominant and one recessive allele (heterozygous), only the dominant phenotype is shown. A dominant allele is represented by a capital letter (e.g. B) and recessive by a lower-case letter (e.g. b).", acceptedAnswers: ["Dominant allele is expressed with just one copy; recessive only shows if two copies are present", "Dominant masks recessive when both are present (heterozygous); recessive only expressed when homozygous", "A dominant allele (capital letter) shows in heterozygotes; recessive (lower case) only shows in homozygous recessive individuals", "Dominant = expressed regardless; recessive = only expressed if no dominant allele is present"], marks: 2, hint: "What does heterozygous (Bb) look like? That tells you which is dominant." },
    { question: "[Biology] Define the terms genotype, phenotype, homozygous, and heterozygous.", answer: "Genotype: the genetic makeup of an organism — the alleles it carries (e.g. Bb). Phenotype: the observable characteristics of an organism resulting from its genotype and environment (e.g. brown eyes). Homozygous: both alleles are the same (e.g. BB or bb). Heterozygous: the two alleles are different (e.g. Bb).", acceptedAnswers: ["Genotype = allele combination (Bb); phenotype = observable trait; homozygous = same alleles (BB/bb); heterozygous = different alleles (Bb)", "Genotype is the alleles an organism has; phenotype is how they are expressed; homozygous = matching alleles; heterozygous = different alleles", "Genotype (genetic makeup), phenotype (observable characteristics), homozygous (identical alleles), heterozygous (different alleles)", "BB or bb = homozygous; Bb = heterozygous; the alleles = genotype; what you see = phenotype"], marks: 2, hint: "Four definitions — one for each term. Genotype is the code; phenotype is the result." },
    // Biology - Ecology
    { question: "[Biology] What is meant by biodiversity? Why is it important?", answer: "Biodiversity refers to the variety of all living organisms in an area — including the variety of different species (species diversity), the genetic variety within a species, and the range of different ecosystems. High biodiversity is important because: ecosystems with more species are more stable and resilient to change; many species provide resources used by humans (food, medicine, raw materials); loss of one species can affect the whole food web.", acceptedAnswers: ["Biodiversity = variety of species in an ecosystem; important for stability, food webs, and human resources", "The range of different species and genetic variation in an area; high biodiversity makes ecosystems more stable and resilient", "Biodiversity is the variety of all living things; it matters because ecosystems depend on species interactions and we rely on them for food and medicine", "Variety of life in an ecosystem; important because each species plays a role and loss disrupts the balance"], marks: 2, hint: "Define biodiversity (variety of living things), then give two reasons why it matters." },
    { question: "[Biology] State two human activities that reduce biodiversity.", answer: "Deforestation (clearing forests for agriculture or development) destroys habitats, displacing or killing species. Pollution (e.g. from agriculture run-off, plastics, industrial chemicals) kills organisms and damages ecosystems. Other examples include: overfishing (depleting fish populations), monoculture farming (reduces species variety), and burning fossil fuels (climate change alters habitats).", acceptedAnswers: ["Deforestation and pollution reduce biodiversity by destroying habitats and killing organisms", "Deforestation removes habitats; overfishing depletes species; both reduce biodiversity", "Farming monocultures and deforestation reduce the variety of species in an ecosystem", "Human activities: habitat destruction (building/farming), pollution (chemicals/plastics) — both reduce biodiversity"], marks: 2, hint: "Think about what destroys habitats or kills organisms directly. Name two specific activities." },
    // Chemistry - Atomic structure
    { question: "[Chemistry] State the relative charges and masses of a proton, neutron, and electron.", answer: "Proton: relative charge +1, relative mass 1. Neutron: relative charge 0 (neutral), relative mass 1. Electron: relative charge −1, relative mass 1/1836 (approximately 0, negligible). Protons and neutrons are found in the nucleus; electrons orbit the nucleus in shells (energy levels).", acceptedAnswers: ["Proton: +1 charge, mass 1. Neutron: 0 charge, mass 1. Electron: -1 charge, negligible mass", "Proton (+1, 1); neutron (0, 1); electron (-1, 1/1836 or approximately 0)", "Protons and neutrons both have relative mass 1; electrons have negligible mass. Proton = +1, neutron = 0, electron = -1", "Subatomic particles: p+ (mass 1, +1), n0 (mass 1, 0), e- (negligible mass, -1)"], marks: 2, hint: "Fill in a table: particle, charge, mass. Electrons have negligible mass." },
    { question: "[Chemistry] What is the difference between atomic number and mass number?", answer: "The atomic number (proton number) is the number of protons in the nucleus — it defines which element it is. The mass number is the total number of protons plus neutrons in the nucleus. Number of neutrons = mass number − atomic number. Isotopes are atoms of the same element (same atomic number) with different mass numbers (different numbers of neutrons).", acceptedAnswers: ["Atomic number = number of protons; mass number = protons + neutrons; neutrons = mass number − atomic number", "Atomic number defines the element (protons only); mass number includes both protons and neutrons", "Atomic number = proton count; mass number = protons + neutrons; same atomic number but different mass number = isotope", "Proton number = atomic number; mass number = proton number + neutron number"], marks: 2, hint: "Atomic number counts protons. Mass number counts protons AND neutrons. How do you find neutrons?" },
    // Chemistry - Bonding
    { question: "[Chemistry] Describe the structure of a giant ionic lattice and explain why ionic compounds have high melting points.", answer: "A giant ionic lattice consists of a regular 3D arrangement of oppositely charged ions held together by strong electrostatic forces of attraction acting in all directions. There are very large numbers of these ionic bonds throughout the structure. To melt an ionic compound, energy must be supplied to overcome all these strong electrostatic attractions between the many ions. This requires a large amount of energy, resulting in high melting and boiling points.", acceptedAnswers: ["Giant ionic lattice = regular 3D arrangement of ions with strong electrostatic forces; high mp because many strong bonds must all be broken", "Ions in a regular lattice held by electrostatic attraction; high melting point because a lot of energy is needed to break many strong ionic bonds", "Strong forces hold positive and negative ions in a lattice; melting requires breaking these forces throughout the structure — needs lots of energy", "3D lattice of oppositely charged ions; high melting point due to strong electrostatic attractions between many ions"], marks: 2, hint: "Describe the structure, then explain WHY the melting point is high (link to the bonds that must be broken)." },
    // Chemistry - Quantitative chemistry
    { question: "[Chemistry] State the formula for calculating the number of moles from mass and relative formula mass.", answer: "Moles = mass (g) / relative formula mass (Mr). Rearranged: mass = moles × Mr; Mr = mass / moles. The relative formula mass is the sum of the relative atomic masses (Ar) of all atoms in the formula. Example: Mr of H₂O = (2 × 1) + 16 = 18, so 18 g of water = 1 mole.", acceptedAnswers: ["moles = mass / Mr; or n = m / Mr", "Number of moles = mass in grams ÷ relative formula mass", "n = m/Mr; rearranged: m = n × Mr or Mr = m/n", "Moles equals mass divided by Mr; example: 18 g of water (Mr=18) = 1 mole"], marks: 2, hint: "The mole equation is n = m/Mr. What are the units of each quantity?" },
    // Chemistry - Chemical changes
    { question: "[Chemistry] What is electrolysis? Name the two electrodes and state what happens at each.", answer: "Electrolysis is the decomposition of an ionic compound (molten or dissolved in water) using an electric current. The electrodes are: anode (positive electrode) — negative ions (anions) are attracted here and lose electrons (oxidation); cathode (negative electrode) — positive ions (cations) are attracted here and gain electrons (reduction). The electrolyte must be molten or in solution for the ions to move and carry charge. Memory aid: OIL RIG — Oxidation Is Loss, Reduction Is Gain (of electrons).", acceptedAnswers: ["Electrolysis uses electricity to decompose ionic compounds; cathode attracts cations (reduced); anode attracts anions (oxidised)", "Anode = positive electrode, oxidation (anions lose electrons); cathode = negative electrode, reduction (cations gain electrons)", "Electrolysis breaks ionic compounds; at cathode: reduction (cations gain e-); at anode: oxidation (anions lose e-)", "Ionic compound in solution is decomposed by electricity; anode = oxidation, cathode = reduction"], marks: 2, hint: "OILRIG — oxidation at the anode, reduction at the cathode. Which ions go to which electrode?" },
    // Chemistry - Organic
    { question: "[Chemistry] What is crude oil? How is it separated into useful fractions?", answer: "Crude oil is a mixture of hydrocarbons (compounds of hydrogen and carbon only) formed from the remains of ancient marine organisms over millions of years. It is separated by fractional distillation: the crude oil is heated and vapourised; the vapour rises up a fractionating column which is hotter at the bottom and cooler at the top; different fractions (groups of hydrocarbons) condense at different temperatures (boiling point ranges) and are collected at different levels. Shorter-chain hydrocarbons (e.g. petrol) condense near the top (lower bp); longer-chain ones (e.g. fuel oil) condense near the bottom (higher bp).", acceptedAnswers: ["Crude oil is a hydrocarbon mixture separated by fractional distillation based on different boiling points", "Mixture of hydrocarbons separated by fractional distillation — different fractions condense at different temperatures in the column", "Crude oil is distilled: heated to vapour, rises up column, fractions condense according to their boiling points", "Fractional distillation separates crude oil: shorter chains condense at top (lower bp); longer chains at bottom (higher bp)"], marks: 2, hint: "What is crude oil made of? How does fractional distillation separate it? (Think boiling points.)" },
    { question: "[Chemistry] What is the difference between alkanes and alkenes?", answer: "Alkanes are saturated hydrocarbons — they contain only single carbon-carbon bonds (C–C). General formula: CₙH₂ₙ₊₂. Example: methane (CH₄), ethane (C₂H₆). Alkenes are unsaturated hydrocarbons — they contain at least one carbon-carbon double bond (C=C). General formula: CₙH₂ₙ. Example: ethene (C₂H₄). Alkenes are more reactive than alkanes and decolourise bromine water (used as a test for the C=C bond).", acceptedAnswers: ["Alkanes have single C-C bonds (saturated); alkenes have a C=C double bond (unsaturated); alkenes decolourise bromine water", "Alkanes: CnH2n+2, only single bonds; alkenes: CnH2n, have a double bond; test with bromine water (turns colourless if alkene)", "Saturated (alkanes, single bonds) vs unsaturated (alkenes, double bond); alkenes are more reactive", "Alkenes contain a C=C double bond (unsaturated); alkanes only have single bonds (saturated); alkenes decolourise bromine water"], marks: 2, hint: "Single bond = saturated = alkane. Double bond = unsaturated = alkene. What is the test for an alkene?" },
    // Chemistry - Earth and atmosphere
    { question: "[Chemistry] Name three greenhouse gases and explain how they contribute to climate change.", answer: "The three main greenhouse gases are: carbon dioxide (CO₂) — released by burning fossil fuels and deforestation; methane (CH₄) — released by livestock, rice paddies, and landfill sites; water vapour (H₂O). These gases allow short-wave solar radiation to pass through the atmosphere but absorb and re-emit long-wave infrared radiation from Earth's surface, trapping heat in the atmosphere (the greenhouse effect). This enhanced greenhouse effect due to human activity is causing global temperatures to rise — climate change.", acceptedAnswers: ["CO2, methane, and water vapour; they trap infrared radiation from Earth, causing global warming", "Carbon dioxide from burning fuels, methane from livestock, water vapour — all absorb heat from Earth and re-emit it, raising temperature", "Greenhouse gases: CO2, CH4, H2O vapour; they trap heat by absorbing infrared radiation, enhancing the greenhouse effect and causing climate change", "CO2, methane, and water vapour prevent Earth's heat from escaping to space, raising global temperatures"], marks: 2, hint: "Name three gases, then explain the mechanism: they absorb infrared radiation from Earth and trap heat." },
    // Physics - Energy
    { question: "[Physics] List five stores of energy.", answer: "Energy stores include: (1) kinetic energy store (moving objects); (2) gravitational potential energy store (objects at height); (3) elastic potential energy store (stretched/compressed objects); (4) thermal (heat) energy store (warm objects); (5) chemical energy store (food, fuels, batteries). Others include nuclear, magnetic, and electrostatic energy stores.", acceptedAnswers: ["Kinetic, gravitational potential, elastic potential, thermal, and chemical energy stores", "Five energy stores: kinetic, GPE, elastic potential, thermal, chemical", "KE, GPE, elastic, thermal, chemical — five main energy stores", "Energy stores: kinetic, gravitational, elastic, thermal, chemical (and nuclear/magnetic/electrostatic)"], marks: 2, hint: "Think about different situations: moving objects, objects at height, stretched springs, warm objects, food/fuel." },
    { question: "[Physics] State the equation for efficiency and explain why no device is 100% efficient.", answer: "Efficiency = useful output energy transfer / total input energy transfer (×100 for percentage). Or: efficiency = useful power output / total power input. No device is 100% efficient because some energy is always dissipated (wasted) as thermal energy (heat) due to friction or resistance, and sometimes also as sound. This energy spreads out into the surroundings and becomes less useful.", acceptedAnswers: ["Efficiency = useful output / total input; never 100% because energy is always wasted as heat (friction/resistance)", "Efficiency = useful energy out / energy in × 100%; devices always lose some energy as thermal energy to surroundings", "Useful output ÷ total input; less than 100% because friction and resistance waste energy as heat", "Efficiency equation: useful output/total input; energy is always lost to the environment as heat or sound"], marks: 2, hint: "State the equation, then explain where the wasted energy goes (friction → heat)." },
    // Physics - Electricity
    { question: "[Physics] What is the difference between current and voltage?", answer: "Current (I) is the rate of flow of electric charge, measured in amperes (A). It is the same in all parts of a series circuit. Voltage (V, or potential difference, pd) is the energy transferred per unit charge, measured in volts (V). It is the 'push' driving current around the circuit. In a series circuit voltages add up; in a parallel circuit the voltage across each branch is the same as the supply voltage.", acceptedAnswers: ["Current is the rate of charge flow (A); voltage is energy per unit charge (V) — the 'push' driving current", "Current (amperes) = flow of charge; voltage (volts) = energy per coulomb, driving the current", "Current is charge per second; pd/voltage is energy transferred per coulomb; I measured in A, V in volts", "Current = rate of charge flow; voltage = potential difference that drives the current; different behaviours in series/parallel circuits"], marks: 2, hint: "Current is the flow; voltage is the driving force. What units does each use?" },
    { question: "[Physics] State the difference between a.c. and d.c. electricity.", answer: "Direct current (d.c.) flows in one direction only — the current does not change direction. Example: current from a battery. Alternating current (a.c.) regularly reverses direction — the current and voltage alternate back and forth. In the UK mains supply: frequency = 50 Hz, voltage ≈ 230 V (rms). Generators produce a.c. Transformers only work with a.c.", acceptedAnswers: ["DC flows in one direction; AC regularly reverses direction; UK mains is AC at 230V/50Hz", "Direct current = constant direction (battery); alternating current = regularly changes direction (mains supply, 230V, 50Hz)", "DC: one direction only. AC: direction reverses 50 times per second (50 Hz); mains supply is AC", "AC alternates direction (UK: 230V, 50Hz); DC is one-directional (batteries); transformers need AC"], marks: 2, hint: "DC = one direction (battery). AC = alternating direction (mains supply). What are the UK mains values?" },
    // Physics - Particle model
    { question: "[Physics] Describe the arrangement and movement of particles in solids, liquids, and gases.", answer: "Solid: particles are closely packed in a regular arrangement. They vibrate about fixed positions but do not move freely. Strong forces hold them in place. Definite shape and volume. Liquid: particles are close together but in a random arrangement. They can flow past each other. Definite volume but no fixed shape. Gas: particles are far apart, in a random arrangement, and move quickly in all directions. Weak forces between them. No definite shape or volume — they fill and expand to fill any container.", acceptedAnswers: ["Solid: regular, closely packed, vibrate in place. Liquid: random, close, can flow. Gas: far apart, random, move fast in all directions", "Solid particles vibrate in fixed positions; liquid particles flow past each other; gas particles move randomly and rapidly with large gaps", "In solids: regular close packing; liquids: close but mobile; gases: far apart and fast-moving", "Solids have fixed positions and shapes; liquids can flow; gases expand to fill containers — all have increasing particle energy"], marks: 2, hint: "For each state: describe spacing, arrangement, and movement of particles." },
    // Physics - Atomic physics
    { question: "[Physics] Name the three types of nuclear radiation and state their nature.", answer: "Alpha (α): a helium nucleus — 2 protons and 2 neutrons. Positively charged. Least penetrating (stopped by paper or a few cm of air). Most ionising. Beta (β): a fast-moving electron emitted from the nucleus when a neutron changes to a proton. Negatively charged. Stopped by a few mm of aluminium. Gamma (γ): high-energy electromagnetic radiation. No charge, no mass. Most penetrating (requires thick lead or concrete to significantly reduce). Least ionising.", acceptedAnswers: ["Alpha = helium nucleus (+2), least penetrating; beta = electron (-1), aluminium stops it; gamma = EM radiation, most penetrating, stopped by lead", "Alpha: 2p+2n, +2 charge, stopped by paper. Beta: electron, stopped by aluminium. Gamma: EM wave, stopped by lead/concrete", "Three types: α (helium nucleus), β (electron from nucleus), γ (electromagnetic wave); penetrating power increases α < β < γ", "Alpha particle, beta particle (electron), gamma ray; penetrating power: alpha < beta < gamma; ionising power: alpha > beta > gamma"], marks: 2, hint: "What is each type made of? What charge does it carry? What material stops it?" },
    // Physics - Forces
    { question: "[Physics] State Newton's Second Law and write it as an equation.", answer: "Newton's Second Law states that the resultant force acting on an object is directly proportional to the acceleration it produces, and inversely proportional to the mass of the object. Equation: F = ma, where F = resultant force (N), m = mass (kg), a = acceleration (m/s²). If the resultant force is doubled, acceleration doubles (at constant mass). If the mass doubles, acceleration halves (at constant force).", acceptedAnswers: ["F = ma; resultant force = mass × acceleration; force and acceleration are proportional", "Newton's 2nd Law: F = ma where F is in newtons, m in kg, a in m/s²", "Resultant force = mass × acceleration (F = ma); greater force → greater acceleration; greater mass → less acceleration", "F = ma; the resultant force equals mass times acceleration"], marks: 2, hint: "State the law in words, then give the equation F = ma with units for each quantity." },
    { question: "[Physics] What factors affect the stopping distance of a car?", answer: "Stopping distance = thinking distance + braking distance. Thinking distance depends on: reaction time of the driver — increased by tiredness, alcohol, drugs, or distractions. Braking distance depends on: vehicle speed (most significant — doubles stopping distance when speed doubles, quadruples when speed doubles, due to KE = ½mv²); road condition (ice/wet roads reduce friction); tyre condition (worn tyres have less grip); brake condition (worn brakes are less effective); mass of vehicle.", acceptedAnswers: ["Stopping distance = thinking + braking distance; affected by speed, road/tyre condition, driver reaction time, and brake quality", "Thinking distance affected by reaction time (alcohol, tiredness); braking distance by speed, road grip, tyre and brake condition", "Higher speed → much greater braking distance (KE ∝ v²); poor conditions (wet roads, worn tyres) also increase stopping distance", "Factors: driver reaction time (thinking distance), speed, road surface, tyre condition, brake condition (braking distance)"], marks: 2, hint: "Split into thinking distance and braking distance. What affects each?" },
    // Physics - Waves
    { question: "[Physics] State the difference between transverse and longitudinal waves.", answer: "In a transverse wave, the oscillation (vibration) is perpendicular (at right angles) to the direction of wave travel. Examples: all electromagnetic waves, water waves, S-waves. In a longitudinal wave, the oscillation is parallel to (along the same direction as) the direction of wave travel. Example: sound waves, P-waves. Longitudinal waves have regions of compression (high pressure) and rarefaction (low pressure).", acceptedAnswers: ["Transverse: oscillation perpendicular to direction of travel (e.g. light). Longitudinal: oscillation parallel to direction of travel (e.g. sound)", "Transverse waves vibrate at right angles to the direction of propagation; longitudinal waves vibrate along the same direction", "Transverse: EM waves, water waves — displacement perpendicular to travel. Longitudinal: sound waves — compressions and rarefactions along the direction of travel", "Transverse = perpendicular vibrations (light). Longitudinal = parallel vibrations (sound) with compressions and rarefactions"], marks: 2, hint: "The key difference is whether the vibration is at right angles or along the direction of travel." },
    // Physics - Magnetism
    { question: "[Physics] What is a magnetic field? Describe the field around a bar magnet.", answer: "A magnetic field is a region where magnetic materials (and current-carrying conductors) experience a force. It is represented by field lines showing the direction of force on a north magnetic pole. Around a bar magnet: field lines emerge from the north pole and enter the south pole. They are closest together near the poles (where the field is strongest) and spread out further from the magnet (where the field is weaker). Field lines never cross.", acceptedAnswers: ["A region where magnetic forces act; field lines go from north to south pole, closest at poles where field is strongest", "Magnetic field: region where magnets/moving charges experience a force; field lines from N to S pole, densest at the poles", "Field lines emerge from north, enter south; closer lines = stronger field; field is strongest at the poles", "A magnetic field exerts forces on magnetic materials; bar magnet field lines curve from north to south pole, strongest near poles"], marks: 2, hint: "Define magnetic field, then describe the pattern of field lines: direction, where they are closest, where the field is strongest." },
  ],
  mid: [
    // --- EXISTING 11 MID QUESTIONS (kept unchanged) ---
    { question: "[Physics] A student measures the extension of a spring at different forces. Explain how to find the spring constant and identify the elastic limit.", answer: "Plot extension (y-axis) against force (x-axis). The linear section shows where Hooke's Law applies (F = ke). The spring constant k = gradient = F/e (N/m). The point where the line becomes non-linear is the elastic limit — beyond this, the spring is permanently deformed (inelastic deformation) and does not return to its original length. Units of k are N/m.", acceptedAnswers: ["Plot force vs extension; k = gradient of the straight section (F/e in N/m); elastic limit is where the line curves", "Spring constant = force ÷ extension from the linear part of the graph; beyond the elastic limit the spring is permanently deformed", "From a force-extension graph: k = slope of the straight portion; the elastic limit is where the graph stops being linear", "k = F/e from the Hooke's Law region of the graph; the kink where the line bends is the elastic limit"], marks: 4, hint: "Describe the graph shape. How do you get k from the graph? What does the curve after the elastic limit mean?" },
    { question: "[Biology] Explain the difference between aerobic and anaerobic respiration, including word equations and a comparison of energy yield.", answer: "Aerobic: glucose + oxygen → carbon dioxide + water. Occurs continuously in mitochondria. Releases approximately 38 ATP per glucose molecule — very efficient. Anaerobic in humans: glucose → lactic acid. Produces only 2 ATP. Lactic acid builds up in muscles causing fatigue and pain; is broken down in the liver after exercise ('oxygen debt'). Anaerobic in yeast (fermentation): glucose → ethanol + carbon dioxide. Used in baking and brewing. Aerobic is preferred because it releases far more energy per glucose molecule.", acceptedAnswers: ["Aerobic produces ~38 ATP from glucose + O2 → CO2 + water; anaerobic only 2 ATP and produces lactic acid or ethanol", "Aerobic respiration in mitochondria is much more efficient than anaerobic; anaerobic creates lactic acid in humans and ethanol in yeast", "Both break down glucose but aerobic needs oxygen and is far more efficient; anaerobic is quick but produces little energy and waste products", "Aerobic: 38 ATP, CO2 + water. Anaerobic: 2 ATP, lactic acid (humans) or ethanol + CO2 (yeast); aerobic is far more efficient"], marks: 4, hint: "Give both equations, compare ATP yield, explain what happens to lactic acid" },
    { question: "[Chemistry] A student adds magnesium to dilute hydrochloric acid. Describe what is observed and write a balanced symbol equation.", answer: "Observations: bubbles of gas are produced (hydrogen), the magnesium gradually dissolves, the reaction mixture warms up (exothermic). The magnesium ribbon may fizz and disappear. Word equation: magnesium + hydrochloric acid → magnesium chloride + hydrogen. Symbol equation: Mg + 2HCl → MgCl₂ + H₂. The hydrogen gas can be tested with a lit splint — it produces a squeaky pop. Magnesium chloride remains in solution.", acceptedAnswers: ["Bubbles of H2, magnesium dissolves, mixture warms; Mg + 2HCl → MgCl2 + H2", "Magnesium fizzes and disappears, gas produced (squeaky pop test = H2); balanced equation: Mg + 2HCl → MgCl2 + H2", "Observations: fizzing, Mg dissolves, heat produced. Equation: Mg + 2HCl → MgCl₂ + H₂", "The ribbon dissolves with effervescence; hydrogen gas is produced; word equation: magnesium + hydrochloric acid → magnesium chloride + hydrogen"], marks: 4, hint: "Describe the visual changes, state the products, and write the balanced equation. Don't forget the gas test." },
    { question: "[Biology] Describe how the kidneys filter the blood and maintain water balance.", answer: "Blood is filtered in the kidneys under high pressure in the glomerulus (filtration). Small molecules pass into the Bowman's capsule: glucose, water, urea, ions. Useful substances are selectively reabsorbed back into the blood — all glucose is reabsorbed, along with the amount of water and ions needed. The remaining filtrate becomes urine: water, urea, and excess ions. The hormone ADH (antidiuretic hormone, released by the pituitary gland) controls water reabsorption — when blood water concentration is low, more ADH is released, causing more water to be reabsorbed, producing small amounts of concentrated urine.", acceptedAnswers: ["Glomerulus filters blood under pressure; useful substances are reabsorbed; ADH controls how much water is reabsorbed", "Ultrafiltration in the glomerulus removes small molecules; selective reabsorption returns glucose and needed water; ADH regulates water balance", "Kidneys filter blood in the glomerulus, reabsorb glucose and water, then ADH adjusts water reabsorption according to blood concentration", "High-pressure filtration removes small molecules; glucose is all reabsorbed; ADH from the pituitary gland controls water recovery"], marks: 5, hint: "Describe filtration, selective reabsorption, and the role of ADH — what triggers ADH and what does it do?" },
    { question: "[Physics] Explain how a transformer works and state the transformer equation.", answer: "A transformer consists of two coils of wire (primary and secondary) wound around an iron core. An alternating current (AC) in the primary coil creates a changing magnetic field in the iron core. This changing magnetic field induces an alternating voltage in the secondary coil (electromagnetic induction). Step-up transformers increase voltage (secondary coil has more turns). Step-down transformers decrease voltage (secondary coil has fewer turns). Transformer equation: Vp/Vs = np/ns, where V = voltage (V) and n = number of turns. For an ideal transformer: Vp × Ip = Vs × Is (power in = power out).", acceptedAnswers: ["AC in primary coil → changing magnetic field in iron core → voltage induced in secondary coil; Vp/Vs = np/ns", "Transformers use electromagnetic induction: changing AC creates changing magnetic flux which induces voltage in the secondary coil; equation: Vp/Vs = np/ns", "Primary coil AC → alternating magnetic field → EMF induced in secondary; step-up has more secondary turns; Vp × Ip = Vs × Is", "Changing magnetic field in iron core links primary and secondary coils; transformer ratio Vp:Vs = np:ns"], marks: 4, hint: "Explain the role of AC, the magnetic field, and electromagnetic induction. State and apply the equation." },
    { question: "[Chemistry] Explain the extraction of aluminium from its ore by electrolysis. Why cannot aluminium be extracted by reduction with carbon?", answer: "Aluminium is extracted from aluminium oxide (Al₂O₃) in bauxite by electrolysis. The aluminium oxide is dissolved in molten cryolite (to lower the melting point, reducing energy costs) and electrolysed. At the cathode (negative electrode): Al³⁺ + 3e⁻ → Al (aluminium is deposited as liquid metal). At the anode (positive electrode): 2O²⁻ → O₂ + 4e⁻ (oxygen gas is produced). Carbon anodes are gradually burned away by the oxygen and must be replaced regularly. Aluminium cannot be extracted by carbon reduction because it is more reactive than carbon — carbon cannot displace it from its oxide. Only metals below carbon in the reactivity series can be extracted this way.", acceptedAnswers: ["Al2O3 dissolved in molten cryolite is electrolysed; Al deposits at cathode, O2 at anode; carbon cannot reduce Al because Al is above carbon in reactivity series", "Electrolysis of molten Al2O3 in cryolite; cathode: Al3+ + 3e- → Al; anode: O2 released; carbon reduction fails because Al is more reactive than carbon", "Al is too reactive for carbon reduction — it must be electrolysed; cryolite lowers the melting point of the ore to save energy", "Aluminium is extracted by electrolysis of aluminium oxide in cryolite; more reactive than carbon so cannot be reduced by it"], marks: 5, hint: "Describe the electrode reactions. Why is cryolite used? Why not carbon? What is the reactivity series argument?" },
    { question: "[Biology] Describe how the immune system responds to a new pathogen, including the roles of phagocytes and lymphocytes.", answer: "When a pathogen enters the body: 1. Phagocytes (non-specific white blood cells) engulf and digest pathogens in a process called phagocytosis — this is the immediate, non-specific response. 2. Lymphocytes (specific white blood cells) recognise the antigen (specific protein on the pathogen's surface) and produce complementary antibodies. Antibodies bind to the antigen, neutralising the pathogen or marking it for destruction (agglutination). 3. Memory lymphocytes remain in the blood after the infection is cleared. On a second exposure to the same antigen, these memory cells allow a faster and stronger antibody response, preventing illness. This is the basis of vaccination: introducing antigens safely to trigger memory cell production without causing disease.", acceptedAnswers: ["Phagocytes engulf pathogens immediately; lymphocytes produce specific antibodies; memory cells provide long-term immunity", "Non-specific phagocytosis first; then specific lymphocytes make antibodies against antigens; memory cells remain for future protection", "Phagocytes digest pathogens; lymphocytes produce complementary antibodies; memory lymphocytes enable rapid secondary response", "Immune response: phagocytosis (non-specific) → antibody production by lymphocytes (specific) → memory cells for immunity"], marks: 5, hint: "First line = phagocytes (engulf). Then lymphocytes (antibodies). Don't forget memory cells for immunity." },
    { question: "[Physics] A student drops a ball from rest at height 2 m. Calculate the speed at which it hits the ground. (g = 10 m/s²)", answer: "Using energy conservation: GPE at top = KE at bottom. mgh = ½mv². The mass cancels: gh = ½v². v² = 2gh = 2 × 10 × 2 = 40. v = √40 ≈ 6.3 m/s. Alternatively using kinematics: v² = u² + 2as = 0 + 2 × 10 × 2 = 40, so v ≈ 6.3 m/s. Both methods give the same answer (assuming no air resistance).", acceptedAnswers: ["v = √(2gh) = √(2 × 10 × 2) = √40 ≈ 6.3 m/s", "Using v² = u² + 2as: v² = 0 + 2(10)(2) = 40, v ≈ 6.32 m/s", "GPE = KE: mgh = ½mv², v = √(2 × 10 × 2) ≈ 6.3 m/s", "6.3 m/s (using energy conservation or kinematics equation)"], marks: 4, hint: "Use either energy conservation (GPE = KE) or kinematics (v² = u² + 2as). The mass cancels in the energy method.", calculator: true },
    { question: "[Chemistry] Explain what is meant by atom economy and percentage yield. Why are both important in industrial chemistry?", answer: "Atom economy = (mass of desired product / total mass of reactants) × 100%. It measures how much of the reactant mass ends up in the desired product. High atom economy = less waste, more sustainable. Percentage yield = (actual yield / theoretical yield) × 100%. It measures how much product was actually obtained compared to the maximum possible. Percentage yield < 100% because: reaction may be incomplete, product is lost during transfer or purification, or side reactions occur. In industry, high atom economy reduces raw material costs and waste disposal costs; high percentage yield means more product per reaction run. Both are important for economic and environmental sustainability.", acceptedAnswers: ["Atom economy = (desired product mass / total reactant mass) × 100%; % yield = (actual / theoretical) × 100%; both matter for cost and sustainability", "High atom economy means less waste; high % yield means more product obtained; both reduce cost and environmental impact", "Atom economy measures how efficiently reactant atoms end up in the product; % yield measures how much product is actually made compared to the theoretical maximum", "Both indicate efficiency: atom economy shows waste in the reaction design; % yield shows waste in the actual process"], marks: 4, hint: "Define each clearly. Then explain why each matters for industry — think cost and waste." },
    { question: "[Biology] Explain how natural selection leads to the evolution of antibiotic resistance in bacteria.", answer: "In a population of bacteria, random mutations cause some individuals to have genes that make them resistant to an antibiotic. When the antibiotic is introduced, non-resistant bacteria are killed, but resistant bacteria survive (they are naturally selected — they have a selective advantage). Resistant bacteria reproduce (rapidly, by binary fission), passing the resistance genes to offspring. Over time, the proportion of resistant bacteria in the population increases. Eventually, the antibiotic becomes ineffective against the population. This is an example of directional natural selection driven by the environmental pressure of the antibiotic.", acceptedAnswers: ["Random mutation → some bacteria resistant → antibiotic kills non-resistant → resistant survive and reproduce → resistance spreads through population", "Variation in resistance exists; antibiotic selects for resistant bacteria; they reproduce passing on resistance genes; population becomes resistant", "Natural selection: resistant mutants survive the antibiotic, reproduce, and pass on resistance genes until most bacteria are resistant", "Mutation creates variation; the antibiotic is the selection pressure; resistant bacteria have selective advantage and pass on genes to offspring"], marks: 5, hint: "Use the key words: variation → selection pressure → survival of the fittest → reproduction → inheritance → change in population" },
    { question: "[Physics] Describe the nuclear model of the atom and explain how Rutherford's gold foil experiment led to the replacement of the plum pudding model.", answer: "The plum pudding model proposed by J.J. Thomson imagined the atom as a diffuse ball of positive charge with electrons embedded throughout (like plums in pudding). Rutherford fired positively charged alpha particles at a very thin gold foil. Most passed straight through (showing the atom is mostly empty space). A small fraction deflected slightly (positive nucleus present). Very rarely, an alpha particle bounced back (nucleus is very small and very dense/massive). Conclusion: the atom has a tiny, dense, positively charged nucleus surrounded by electrons in a mostly empty space — the nuclear model. Niels Bohr later added that electrons occupy fixed energy levels (shells).", acceptedAnswers: ["Most alpha particles passed through gold foil; some deflected; a few bounced back — proving a tiny dense positive nucleus surrounded by mostly empty space", "Rutherford's experiment showed atoms are mostly empty with a tiny dense positive nucleus, replacing Thomson's plum pudding model of diffuse positive charge", "Alpha particle scattering: most go straight through (empty space), some deflect (positive nucleus repels), rare back-scatter (dense nucleus) → nuclear model", "The gold foil experiment replaced the plum pudding model by showing charge is concentrated in a tiny nucleus, not spread throughout the atom"], marks: 5, hint: "Describe the plum pudding model. Then describe each observation from the experiment and what each tells us about atomic structure." },
    // --- NEW MID QUESTIONS ---
    // Biology
    { question: "[Biology] Draw and explain a Punnett square for a cross between two heterozygous brown-eyed parents (Bb × Bb), where brown (B) is dominant over blue (b).", answer: "Punnett square: B and b across the top; B and b down the side. The four offspring genotypes are BB, Bb, Bb, bb. Phenotype ratio: 3 brown : 1 blue. Probability of brown eyes = 3/4 (75%); blue eyes = 1/4 (25%). BB = homozygous dominant (brown); Bb = heterozygous (brown, because B is dominant); bb = homozygous recessive (blue). This 3:1 phenotype ratio is characteristic of a monohybrid cross between two heterozygous parents.", acceptedAnswers: ["Punnett square gives BB, Bb, Bb, bb; 3 brown : 1 blue; 75% brown, 25% blue", "Genotypes: 1 BB : 2 Bb : 1 bb; phenotype ratio 3 brown : 1 blue; blue only appears in bb individuals", "Cross Bb × Bb gives 3/4 brown (BB or Bb) and 1/4 blue (bb)", "Punnett square for Bb × Bb: 25% BB, 50% Bb, 25% bb; 3:1 brown to blue ratio"], marks: 4, hint: "Draw the Punnett square. List all four outcomes. State the phenotype ratio and probabilities." },
    { question: "[Biology] Explain the reflex arc and state why reflex actions are important.", answer: "A reflex arc is the pathway of a nerve signal during a reflex action. It follows this order: stimulus → receptor → sensory neurone → (relay neurone in spinal cord) → motor neurone → effector (muscle or gland) → response. The signal travels via synapses between neurones. Reflex actions are automatic, very fast, and do not involve conscious thought (the brain is not part of the arc — though it is informed afterward). They are important because they protect the body from harm (e.g. pulling hand away from a hot object) without the delay of conscious decision-making.", acceptedAnswers: ["Reflex arc: stimulus → receptor → sensory neurone → relay neurone → motor neurone → effector; bypasses conscious thought for a fast protective response", "Receptor detects stimulus; signal travels via sensory neurone, relay neurone, motor neurone to effector; reflex is automatic and fast", "Reflex: stimulus → receptor → sensory → relay (spinal cord) → motor → effector; important because it protects body without conscious processing", "The reflex arc bypasses the brain for fast automatic responses; pathway: sensory neurone → relay neurone → motor neurone → muscle"], marks: 4, hint: "List each step in order (receptor → sensory → relay → motor → effector). Explain why speed matters." },
    { question: "[Biology] Describe the carbon cycle, including the processes that add CO₂ to and remove CO₂ from the atmosphere.", answer: "CO₂ is removed from the atmosphere by: photosynthesis (plants absorb CO₂ and convert it to glucose and organic matter); absorption by oceans. CO₂ is added to the atmosphere by: respiration (all living organisms release CO₂); decomposition (microorganisms break down dead matter, releasing CO₂); combustion (burning of fossil fuels and wood releases stored carbon as CO₂). Carbon is also stored in: oceans, forests, soil organic matter, and fossil fuels. Human activities (burning fossil fuels, deforestation) are increasing CO₂ levels, contributing to the enhanced greenhouse effect and climate change.", acceptedAnswers: ["CO2 removed by photosynthesis and ocean absorption; added by respiration, decomposition, and combustion; humans increase CO2 by burning fuels and deforestation", "Carbon cycle: plants remove CO2 by photosynthesis; organisms add CO2 by respiration; decomposition and combustion also release CO2", "Processes removing CO2: photosynthesis. Processes adding CO2: respiration, combustion, decomposition. Human activity disrupts balance", "Photosynthesis and oceans absorb CO2; respiration, decay, and burning fossil fuels release it; the cycle maintains balance unless disrupted"], marks: 4, hint: "List at least two processes that add CO2 and two that remove it. Mention human impact." },
    // Chemistry - Mid
    { question: "[Chemistry] A student reacts 12 g of carbon with excess oxygen. Calculate the mass of carbon dioxide produced. (Ar: C = 12, O = 16)", answer: "Equation: C + O₂ → CO₂. Mr of C = 12; Mr of CO₂ = 12 + 32 = 44. Moles of C = 12/12 = 1 mole. Mole ratio C : CO₂ = 1 : 1. Therefore moles of CO₂ = 1 mole. Mass of CO₂ = 1 × 44 = 44 g.", acceptedAnswers: ["44 g of CO2 produced; 1 mole of C produces 1 mole of CO2 (Mr=44)", "Moles of C = 12/12 = 1; ratio 1:1; mass CO2 = 1 × 44 = 44 g", "C + O2 → CO2; 12g carbon = 1 mol; 1 mol CO2 = 44 g", "44 g; using moles: n(C)=1, n(CO2)=1, mass = 44 g"], marks: 4, hint: "Write the equation. Calculate moles of C. Use the 1:1 mole ratio. Convert moles of CO2 to mass.", calculator: true },
    { question: "[Chemistry] Explain how increasing temperature and concentration affect the rate of a chemical reaction, using collision theory.", answer: "Increasing temperature: particles gain kinetic energy, so they move faster. This means (1) collisions are more frequent, and (2) a greater proportion of particles have energy equal to or greater than the activation energy. Both effects increase the rate of reaction significantly. Increasing concentration: more particles are present in the same volume. This increases the frequency of collisions between reactant particles — more collisions per unit time, so more successful collisions, increasing the rate. The collision energy is not changed by concentration alone.", acceptedAnswers: ["Temperature: faster particles → more frequent collisions and more particles above activation energy → faster reaction. Concentration: more particles → more collisions → faster reaction", "Higher temperature means more energetic collisions and more particles exceeding activation energy; higher concentration means more frequent collisions", "Increasing temperature increases collision frequency and the proportion of successful collisions; increasing concentration increases collision frequency only", "Temperature raises kinetic energy so more particles have energy ≥ activation energy; concentration puts more particles in the same space, increasing collision rate"], marks: 4, hint: "For temperature: explain both frequency AND energy effects. For concentration: explain only frequency. Use key terms: activation energy, collision frequency." },
    { question: "[Chemistry] Describe how to carry out a titration to find the concentration of an unknown acid using a known concentration of alkali.", answer: "1. Rinse the burette with the acid and fill it with acid. Record the initial burette reading. 2. Use a pipette to measure a fixed volume of alkali into a conical flask. Add two to three drops of indicator (e.g. phenolphthalein — pink in alkali, colourless at endpoint). 3. Add acid from the burette slowly, swirling the flask. Near the endpoint, add drop by drop. 4. Stop when the indicator just changes colour permanently. Record the final burette reading. 5. Calculate the volume of acid used (titre = final − initial reading). 6. Repeat to get concordant results (within 0.10 cm³). 7. Use n = c × V to calculate moles of alkali; use the mole ratio from the equation to find moles of acid; calculate concentration = moles / volume.", acceptedAnswers: ["Fill burette with acid; pipette alkali + indicator into flask; add acid until indicator just changes; record titre; repeat for concordant results; use n=cV to find concentration", "Titration: measure alkali with pipette, add indicator, add acid from burette until endpoint (colour change), read titre, repeat, calculate concentration using moles", "Add acid from burette to alkali+indicator in flask; endpoint = permanent colour change; concordant titres averaged; moles = concentration × volume used to calculate unknown", "Use burette for acid, pipette for alkali; add indicator; record volume at endpoint; repeat for accuracy; use n = cV and mole ratio to find acid concentration"], marks: 5, hint: "Describe each step: filling the burette, adding the indicator, reaching the endpoint, repeating for concordance, and the calculation." },
    // Physics - Mid
    { question: "[Physics] A resistor has a resistance of 15 Ω and a current of 2 A flowing through it. Calculate (a) the potential difference across it and (b) the power dissipated.", answer: "(a) V = IR = 2 × 15 = 30 V. (b) Power P = IV = 2 × 30 = 60 W. (Alternatively: P = I²R = 4 × 15 = 60 W; or P = V²/R = 900/15 = 60 W.) The unit of power is the watt (W).", acceptedAnswers: ["V = 30 V; P = 60 W", "V = IR = 30V; P = IV = 60W or P = I²R = 60W", "Potential difference = 30 volts; power = 60 watts", "V = 2 × 15 = 30 V; P = 2² × 15 = 60 W"], marks: 4, hint: "Use V = IR for part (a). Then use P = IV (or P = I²R) for part (b).", calculator: true },
    { question: "[Physics] Explain what happens to the current and voltage in (a) a series circuit and (b) a parallel circuit when more components are added.", answer: "(a) Series circuit: when more resistors are added in series, total resistance increases (Rtotal = R1 + R2 + ...). Since V is constant (same supply), current decreases (I = V/R). The current is the same at every point. Voltage is shared between components. (b) Parallel circuit: adding more resistors in parallel decreases total resistance (1/Rtotal = 1/R1 + 1/R2 + ...). Voltage across each branch equals the supply voltage. The total current from the supply increases as resistance decreases. Current splits between branches.", acceptedAnswers: ["Series: resistance increases → current decreases, voltage shared; Parallel: resistance decreases → total current increases, voltage constant across each branch", "Series: same current everywhere, voltage divided; adding components reduces current. Parallel: same voltage across branches, total current increases with more paths", "In series, more components mean more resistance and less current; in parallel, more branches mean less total resistance and more total current", "Series: adding resistors increases total R, reduces I, voltage splits. Parallel: adding resistors decreases total R, increases total I, voltage stays same across each branch"], marks: 4, hint: "For series: what happens to total resistance and therefore current? For parallel: how does voltage behave and what happens to current?" },
    { question: "[Physics] A wave has a frequency of 200 Hz and a wavelength of 1.5 m. Calculate the wave speed. Then calculate the wavelength if the speed stays the same but the frequency doubles.", answer: "Part 1: v = f × λ = 200 × 1.5 = 300 m/s. Part 2: frequency doubles to 400 Hz. Since v = fλ and speed stays constant at 300 m/s: λ = v/f = 300/400 = 0.75 m. The wavelength halves when frequency doubles (at constant speed).", acceptedAnswers: ["v = 300 m/s; new wavelength = 0.75 m (halves when frequency doubles)", "300 m/s; 0.75 m — doubling frequency halves wavelength at constant speed", "v = fλ = 200×1.5 = 300 m/s; new λ = 300/400 = 0.75 m", "Wave speed = 300 m/s; when f = 400 Hz, λ = 300/400 = 0.75 m"], marks: 4, hint: "Use v = fλ for part 1. Rearrange to λ = v/f for part 2. What happens to wavelength when frequency doubles?", calculator: true },
    { question: "[Physics] Explain what is meant by half-life and use a decay table to find the half-life if a sample starts with 800 nuclei and decays as follows: 800 → 400 → 200 → 100 every 30 minutes.", answer: "Half-life is the time taken for the number of undecayed nuclei (or the activity) of a radioactive sample to halve. It is constant for any given isotope and cannot be changed by physical or chemical conditions. From the data: 800 → 400 (one half-life), 400 → 200 (second half-life), 200 → 100 (third half-life). Each step takes 30 minutes. Therefore the half-life = 30 minutes.", acceptedAnswers: ["Half-life = 30 minutes; each step the count halves; half-life is the time for activity to halve", "30 minutes — each 30 min the nuclei halve (800→400→200→100); half-life defined as time for count to halve", "The half-life is 30 minutes (the time between each halving of the sample)", "From the table, half-life = 30 min; definition: time for undecayed nuclei to decrease by half"], marks: 4, hint: "Look at the pattern in the numbers — how long does each halving take? Define half-life first." },
    { question: "[Chemistry] Describe how to test for the presence of hydrogen gas, oxygen gas, and carbon dioxide gas.", answer: "Hydrogen: hold a lit splint at the mouth of the test tube — a squeaky pop confirms hydrogen (it burns rapidly). Oxygen: hold a glowing splint at the mouth of the test tube — the splint relights (oxygen supports combustion). Carbon dioxide: bubble the gas through limewater (calcium hydroxide solution) — the limewater turns milky/cloudy (due to calcium carbonate precipitate forming). These tests are standard chemical identification tests used in practical chemistry.", acceptedAnswers: ["H2: lit splint → squeaky pop. O2: glowing splint relights. CO2: limewater turns milky", "Hydrogen = squeaky pop with burning splint; oxygen = glowing splint relights; CO2 = turns limewater cloudy/milky", "Test H2 with lit splint (squeaky pop); O2 with glowing splint (relights); CO2 by bubbling through limewater (goes milky)", "Hydrogen: squeaky pop. Oxygen: relights glowing splint. CO2: limewater turns cloudy/milky white"], marks: 3, hint: "For each gas: state the reagent/test and the positive result. Three separate tests.", required_practical: true },
  ],
  long: [
    // --- EXISTING 5 LONG QUESTIONS (kept unchanged) ---
    { question: "[Biology] Describe the structure and function of the heart and explain how the circulatory system delivers oxygen to cells. (6 marks)", answer: "The heart is a muscular organ with four chambers: two atria (upper, receiving blood) and two ventricles (lower, pumping blood). The right side receives deoxygenated blood from the body and pumps it to the lungs via the pulmonary artery (pulmonary circulation). The left side receives oxygenated blood from the lungs and pumps it to the body via the aorta (systemic circulation). Valves (atrioventricular and semilunar) prevent backflow. Red blood cells carry oxygen bound to haemoglobin. At respiring cells, oxygen diffuses from capillaries down the concentration gradient into cells. CO₂ diffuses back into the blood. The double circulatory system maintains high pressure for efficient delivery.", acceptedAnswers: ["Four chambers: right side pumps to lungs, left side pumps oxygenated blood to body; valves prevent backflow; haemoglobin carries O2 to cells via capillaries", "Right atrium/ventricle → pulmonary circuit; left atrium/ventricle → systemic circuit; O2 diffuses from capillaries to cells; CO2 diffuses back", "Double circulation: pulmonary (heart to lungs) and systemic (heart to body); red blood cells carry O2 using haemoglobin; capillaries allow gas exchange with cells", "Heart pumps blood through two circuits; valves prevent backflow; oxygen transported in RBCs and diffuses into respiring cells at capillaries"], marks: 6, hint: "Describe each chamber's role, trace blood flow through both circulations, explain gas exchange at cells" },
    { question: "[Chemistry] Describe the structure and properties of ionic compounds and covalent compounds. Compare their typical properties with reference to bonding. (6 marks)", answer: "Ionic compounds: giant ionic lattice structure — oppositely charged ions held together by strong electrostatic forces in a regular 3D arrangement. Properties: high melting/boiling points (many strong bonds to break); conduct electricity when molten or dissolved (ions free to move) but not when solid (ions fixed); often soluble in water. Examples: NaCl, MgO. Covalent compounds: atoms share electrons to form covalent bonds. Simple molecular compounds (e.g. H₂O, CO₂): low melting/boiling points (weak intermolecular forces between molecules, though covalent bonds within molecules are strong); do not conduct electricity. Giant covalent structures (e.g. diamond, graphite, SiO₂): very high melting points (many strong covalent bonds to break throughout the lattice).", acceptedAnswers: ["Ionic: giant lattice, high mp, conducts when molten/dissolved. Covalent: shared electrons; simple molecular = low mp; giant covalent = very high mp", "Ionic compounds have strong electrostatic forces in a lattice giving high melting points; simple molecular covalent substances have weak intermolecular forces giving low melting points", "Ionic: high mp, conducts electricity when dissolved, giant lattice. Simple molecular covalent: low mp, does not conduct, weak intermolecular forces", "The high mp of ionic compounds is due to strong electrostatic attractions in the lattice; simple covalent substances have weak forces between molecules so lower mp"], marks: 6, hint: "Define structure and bonding of each, then link each property explicitly to the bonding (e.g. high mp → many strong bonds to break)" },
    { question: "[Physics] Explain the electromagnetic spectrum, including the properties of waves and uses and dangers of different types of radiation. (6 marks)", answer: "The electromagnetic spectrum is a family of transverse waves that all travel at the same speed in a vacuum (3 × 10⁸ m/s). Arranged in order of increasing frequency and decreasing wavelength: radio waves, microwaves, infrared, visible light, ultraviolet, X-rays, gamma rays. All EM waves transfer energy. Higher frequency = more energy. Properties: wavelength, frequency, amplitude, speed. Uses: radio/microwaves — communication and satellite transmission; infrared — heating and thermal imaging; visible — sight and photography; UV — detecting forged bank notes, sterilisation; X-rays — medical imaging, airport security; gamma — cancer treatment (radiotherapy), sterilising medical equipment. Dangers: UV causes skin cancer and eye damage; X-rays and gamma rays are ionising radiation — they can damage or mutate DNA, potentially causing cancer.", acceptedAnswers: ["EM spectrum: radio, microwave, IR, visible, UV, X-ray, gamma — all transverse waves at 3×10⁸ m/s; higher frequency = more energy; ionising radiation (UV, X-ray, gamma) can damage DNA", "All EM waves travel at light speed in a vacuum; ordered by frequency; uses range from communication (radio) to cancer treatment (gamma); ionising radiation is dangerous to cells", "Transverse waves across the spectrum from radio to gamma; each type has specific uses (IR for heating, X-rays for imaging) and dangers (UV/gamma can cause cancer)", "The EM spectrum shares properties: all transverse, same vacuum speed; uses depend on frequency; UV and above are ionising and can mutate DNA"], marks: 6, hint: "Order the spectrum. State properties (speed, wavelength, frequency relationship). Give use AND danger for at least 4 types." },
    { question: "[Biology + Chemistry] Describe how food is chemically digested in the human digestive system, naming the enzymes involved and where they act. (6 marks)", answer: "Chemical digestion breaks large, insoluble food molecules into small, soluble molecules that can be absorbed. Carbohydrates (starch → maltose → glucose): amylase acts in the mouth (saliva) and small intestine (produced by pancreas). Maltase in the small intestine breaks maltose into glucose. Proteins (proteins → amino acids): protease (pepsin in stomach, trypsin from pancreas) acts in the stomach and small intestine. The stomach produces hydrochloric acid (pH 2) — creates optimum pH for pepsin. Lipids (fats → fatty acids + glycerol): lipase acts in the small intestine. Bile (produced by liver, stored in gall bladder) emulsifies fats, increasing surface area for lipase. Products of digestion are absorbed in the small intestine through villi (large surface area, thin walls, rich blood supply).", acceptedAnswers: ["Amylase breaks starch to glucose in mouth/small intestine; protease breaks protein to amino acids in stomach/SI; lipase breaks fats to fatty acids + glycerol in SI; bile emulsifies fats", "Carbohydrates digested by amylase; proteins by protease (pepsin in stomach); fats by lipase in small intestine; bile from liver emulsifies fat droplets", "Starch → glucose (amylase); proteins → amino acids (protease); fats → fatty acids + glycerol (lipase + bile); all products absorbed through villi", "Amylase (starch), protease (protein), lipase (fats) are the three main enzyme types; bile emulsifies fat; absorption through small intestine villi"], marks: 6, hint: "Cover carbohydrate, protein, and fat digestion — name the enzyme, where it acts, and the products. Include role of bile." },
    { question: "[Physics] A student performs an experiment on radioactive decay. Explain what is meant by half-life and describe how to calculate it from a decay graph. Include the uses and dangers of radioactive emissions. (6 marks)", answer: "Half-life is the time taken for half the nuclei in a radioactive sample to decay (or for the count rate/activity to halve). It is constant for any given radioisotope and cannot be changed by temperature, pressure or chemical environment. From a decay graph: draw a horizontal line from the y-axis at half the initial count rate. Drop a vertical line to the x-axis — read off the time. Repeat to verify. Uses: alpha radiation — smoke detectors; beta radiation — thickness gauging in industry; gamma radiation — radiotherapy (cancer treatment), sterilising medical equipment, PET scans; carbon-14 for radiocarbon dating. Dangers: all ionising radiation can damage living cells and DNA, potentially causing cancer or cell death. Alpha is most ionising but least penetrating (stopped by paper or skin); gamma is most penetrating (reduced by thick lead or concrete).", acceptedAnswers: ["Half-life = time for activity/count rate to halve; read from graph; uses: alpha (smoke detectors), beta (thickness), gamma (radiotherapy); all ionising radiation can damage DNA", "Half-life is constant for each isotope; from graph read time for count rate to halve; dangers include DNA damage and cancer; uses include medical imaging and carbon dating", "Time for half the nuclei to decay; found from decay curve; alpha, beta, gamma have different uses and penetrating powers; ionising radiation can mutate DNA", "Half-life: activity halves each period; read from decay graph; gamma used in radiotherapy; all types can damage cells; alpha most ionising, gamma most penetrating"], marks: 6, hint: "Define half-life. Explain how to read it from a graph. Give at least 3 uses (one for each type of emission) and explain the health dangers." },
    // --- NEW LONG QUESTIONS ---
    { question: "[Biology] Evaluate the evidence for and against the use of stem cells in medicine. Consider both embryonic and adult stem cells. (6 marks)", answer: "Arguments for stem cell use: Stem cells could be used to treat many currently incurable conditions such as Parkinson's disease, diabetes, and spinal cord injuries by replacing damaged or destroyed cells. Embryonic stem cells are pluripotent — they can become any cell type, giving them greater therapeutic potential. Adult stem cells (e.g. bone marrow transplants for leukaemia) are already used successfully in medicine with fewer ethical concerns. Arguments against: The use of embryonic stem cells is ethically controversial — the embryo is destroyed in the process, raising objections about the status of human life. There is a risk of immune rejection (unless cells are genetically matched). There is also a risk of uncontrolled cell division (cancer). Therapeutic cloning can overcome immune rejection but is expensive and technically complex. The technology is still experimental for most applications. Overall: the potential benefits are enormous, but ethical concerns and technical limitations must be weighed carefully.", acceptedAnswers: ["Embryonic stem cells are pluripotent (any cell type) but raise ethical issues (embryo destruction); adult stem cells have fewer concerns but are less versatile; risk of rejection and cancer must be considered", "For: treat incurable diseases, pluripotent cells replace any damaged tissue. Against: embryo destruction raises ethics; rejection risk; possible tumour formation", "Stem cells could treat Parkinson's, leukaemia, diabetes; embryonic are most versatile but ethically controversial; adult stem cells already used in bone marrow transplants with fewer objections", "Benefits: disease treatment, replacing damaged cells. Risks: ethical issues with embryo use, immune rejection, uncontrolled division. Balance required"], marks: 6, hint: "Give at least two arguments for and two against. Consider embryonic and adult separately. Include ethical and medical points." },
    { question: "[Chemistry] Describe the process of making a polymer from a monomer, giving an example of an addition polymer and a condensation polymer. Evaluate the environmental impact of polymers. (6 marks)", answer: "Addition polymerisation: unsaturated monomers (containing C=C double bonds, e.g. ethene) join together — the double bond opens and monomers link in a chain with no other products. Product: poly(ethene). Many thousands of ethene molecules form the polymer. Condensation polymerisation: monomers with two functional groups react to form a polymer and release a small molecule (e.g. water) at each step. Examples: nylon (formed from a dicarboxylic acid and a diamine), proteins and DNA (naturally occurring condensation polymers). Environmental impact: most addition polymers are non-biodegradable — they persist in landfill and the ocean for hundreds of years, harming wildlife (plastic pollution). Burning polymers releases toxic gases. Advantages of polymers: lightweight, cheap, durable, waterproof — used in food packaging, clothing, medical devices. Solutions include recycling, biodegradable polymers, and reducing single-use plastic production.", acceptedAnswers: ["Addition: ethene monomers join via C=C double bond → poly(ethene), no other product. Condensation: releases water, e.g. nylon; environmental problems: non-biodegradable, ocean pollution, toxic when burned", "Addition polymerisation (e.g. ethene → poly(ethene)) from alkene monomers; condensation makes nylon releasing water; polymers are non-biodegradable causing landfill and ocean pollution", "Poly(ethene) from ethene addition; nylon from condensation (releases water); environmental impact: non-biodegradable, marine pollution; solutions: recycling and biodegradable alternatives", "Addition polymer example: poly(propene). Condensation: nylon or polyester releasing water. Issue: non-biodegradable plastics cause pollution; recycling and biodegradable plastics are solutions"], marks: 6, hint: "Explain both types with examples. Then evaluate environmental problems and possible solutions. Use named polymers." },
    { question: "[Physics] A student investigates the relationship between force and acceleration using a trolley and hanging masses on a runway. Describe the method, expected results, and sources of error. (6 marks)", answer: "Method: Set up a trolley on a level runway with a string over a pulley connected to a hanging mass (the accelerating force). Attach a ticker tape or use a light gate to measure acceleration. Vary the hanging mass (keeping trolley mass constant) and measure acceleration each time. Keep the runway slightly tilted to compensate for friction (friction compensation). Results: as force increases, acceleration increases proportionally (Newton's Second Law, F = ma). A graph of F vs a should give a straight line through the origin — the gradient = mass. To investigate effect of mass: vary the trolley mass (using extra masses on the trolley) while keeping the hanging mass constant — as mass increases, acceleration decreases. Sources of error: friction in the pulley or on the runway; the string may not be horizontal; the trolley may hit the pulley before measurements are complete; masses being moved from the trolley to the hanging mass changes both force and mass simultaneously (must control this).", acceptedAnswers: ["Trolley and hanging mass; vary force (hanging mass); measure acceleration via light gate or ticker tape; F ∝ a at constant mass; graph is a straight line; error: friction", "Method: vary hanging mass = force, keep trolley mass constant, measure a; results: F ∝ a (straight line from origin); errors include friction and string angle", "Controlled experiment: vary one variable (force or mass), keep other constant; expected: linear F-a graph; errors: friction compensation needed, pulley friction", "Trolley on runway; hanging mass provides force; light gate measures acceleration; F vs a gives straight line through origin; sources of error: friction, pulley resistance"], marks: 6, hint: "Describe the setup, what you vary and keep constant, expected graph shape, and at least two sources of error.", required_practical: true },
  ],
  flashcard: [
    // --- EXISTING 16 FLASHCARDS (kept unchanged) ---
    { term: "Cell Membrane", definition: "A selectively permeable barrier surrounding all cells. Controls what enters and leaves. Made of a phospholipid bilayer with embedded proteins. Allows small molecules (oxygen, water) to pass freely; controls larger molecules using protein channels and carriers.", example: null },
    { term: "Velocity-Time Graph", definition: "A graph showing how velocity changes over time. Gradient = acceleration (m/s²). Area under graph = distance travelled (m). Horizontal line = constant velocity. Downward slope = deceleration. A curve means the acceleration is changing.", example: "A car accelerating: upward slope. Braking: downward slope. Constant speed: horizontal line." },
    { term: "Periodic Table", definition: "Elements arranged in order of increasing atomic number. Elements in the same group have the same number of outer electrons and similar chemical properties. Periods represent the energy level (shell) being filled. Metals are on the left; non-metals on the right; the transition metals are in the middle.", example: "Group 1 (alkali metals): all have 1 outer electron and react vigorously with water" },
    { term: "Enzyme Active Site", definition: "The specific region on an enzyme where the substrate binds. The shape is complementary to the substrate (lock and key model). Enzymes are biological catalysts — they lower activation energy. Extreme temperature or pH denatures the enzyme, altering the shape of the active site so the substrate no longer fits.", example: "Amylase has an active site complementary to starch (its substrate)" },
    { term: "Series and Parallel Circuits", definition: "In series: same current everywhere; voltage is shared between components; total resistance = sum of individual resistances. In parallel: voltage is same across each branch; current splits; total resistance is less than any individual branch resistance. Adding components in parallel decreases total resistance and increases current.", example: "Christmas lights in series: one breaks, all go out. In parallel: one breaks, rest stay on." },
    { term: "Photosynthesis Equation", definition: "Carbon dioxide + water → glucose + oxygen. (6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂). Light energy is absorbed by chlorophyll in the chloroplasts of plant cells. Rate is affected by: light intensity, CO₂ concentration, and temperature.", example: "Limiting factors: in low light, increasing light increases rate; once another factor is limiting, further light has no effect" },
    { term: "DNA and Chromosomes", definition: "DNA (deoxyribonucleic acid) is the genetic material found in the nucleus of cells. It is a double helix made of nucleotide bases (A, T, C, G). Chromosomes are long molecules of DNA. Humans have 46 chromosomes (23 pairs) in most body cells. Each gene is a sequence of bases that codes for a specific protein.", example: "The base sequence A-T-G codes for the amino acid methionine — this is how DNA codes for protein" },
    { term: "Half-Life", definition: "The time taken for half of the undecayed nuclei in a radioactive sample to decay, or for the activity/count rate to halve. Half-life is constant for any given isotope and cannot be altered by physical or chemical conditions. Used in radiocarbon dating (carbon-14, half-life ~5,730 years).", example: "If a sample starts at 800 counts/min and the half-life is 2 hours: after 2 hrs = 400; after 4 hrs = 200; after 6 hrs = 100" },
    { term: "Ionic Bonding", definition: "The electrostatic attraction between oppositely charged ions, formed when electrons are transferred from a metal atom to a non-metal atom. The metal loses electrons to form a positive ion (cation); the non-metal gains electrons to form a negative ion (anion). Results in a giant ionic lattice with high melting point.", example: "Na (2,8,1) loses 1 electron → Na⁺ (2,8). Cl (2,8,7) gains 1 electron → Cl⁻ (2,8,8). NaCl formed." },
    { term: "Newton's Laws of Motion", definition: "1st Law: An object remains at rest or constant velocity unless a resultant force acts on it (inertia). 2nd Law: Resultant force = mass × acceleration (F = ma). The unit of force is the newton (N). 3rd Law: For every action there is an equal and opposite reaction — forces always occur in pairs on different objects.", example: "Rocket: burning gases are pushed down (action); the rocket is pushed up (reaction) — Newton's 3rd Law" },
    { term: "Covalent Bonding", definition: "A shared pair of electrons between two non-metal atoms. Each atom donates one electron to the shared pair. The shared electrons are attracted to both nuclei, holding the atoms together. Simple molecular covalent substances have low melting points (weak intermolecular forces). Giant covalent structures (e.g. diamond) have very high melting points.", example: "O₂: each oxygen shares 2 electrons with the other, forming a double covalent bond" },
    { term: "Natural Selection", definition: "The process by which organisms with advantageous characteristics are more likely to survive, reproduce, and pass on their genes. Key steps: variation (due to mutation), selection pressure (environmental challenge), survival advantage, reproduction, inheritance of favourable traits. Over many generations, the population changes — this is evolution.", example: "Antibiotic resistance: bacteria with a resistance mutation survive antibiotic treatment and reproduce, increasing the proportion of resistant bacteria" },
    { term: "Specific Heat Capacity", definition: "The energy required to raise the temperature of 1 kg of a substance by 1°C. Symbol: c. Units: J/kg/°C. Equation: E = mcΔT. Water has a high specific heat capacity (4,200 J/kg/°C), making it effective for storing and transferring thermal energy.", example: "To heat 2 kg of water by 10°C: E = 2 × 4200 × 10 = 84,000 J" },
    { term: "Homeostasis", definition: "The maintenance of a stable internal environment in the body despite external changes. Controlled by negative feedback mechanisms. Examples: blood glucose regulation (insulin/glucagon from the pancreas), body temperature regulation (sweating, shivering), water balance (ADH and kidneys).", example: "Blood glucose rises after eating → pancreas releases insulin → cells take up glucose → blood glucose falls back to normal" },
    { term: "Electromagnetic Induction", definition: "The process of generating an electric current (or EMF) by changing the magnetic flux through a conductor. Discovered by Faraday. A generator/dynamo uses this principle: rotating a coil in a magnetic field induces an alternating current. The induced EMF is greater if: the coil rotates faster, there are more turns, or the magnet is stronger.", example: "Moving a bar magnet into a coil of wire induces a current — the galvanometer deflects" },
    { term: "Moles", definition: "The mole is the unit for amount of substance. 1 mole = 6.02 × 10²³ particles (Avogadro's number). Moles = mass (g) / relative formula mass (Mr). Used to calculate reacting masses and percentage yield. In solutions: moles = concentration (mol/dm³) × volume (dm³).", example: "Moles of NaCl (Mr = 58.5) in 11.7 g: moles = 11.7 / 58.5 = 0.2 mol" },
    // --- NEW FLASHCARDS ---
    // Biology
    { term: "Mitosis", definition: "A type of cell division producing two genetically identical daughter cells, each with the same number of chromosomes as the parent (diploid). Used for growth, repair, and asexual reproduction. The cell copies its DNA, then divides. The daughter cells are clones of the parent cell.", example: "Skin cells dividing to replace damaged tissue undergo mitosis — all daughter cells are genetically identical" },
    { term: "Osmosis", definition: "The net movement of water molecules through a partially permeable membrane from a region of higher water concentration (dilute solution) to a region of lower water concentration (concentrated solution). It is a passive process — no energy is required. Turgor pressure in plant cells results from water entering by osmosis.", example: "A red blood cell in a very dilute solution will swell (take in water by osmosis) and may burst (lyse)" },
    { term: "Diffusion", definition: "The net movement of particles (molecules or ions) from an area of high concentration to an area of low concentration, down a concentration gradient. Passive — no energy needed. Faster in gases than liquids; increased by higher temperature, steeper gradient, and larger surface area.", example: "Oxygen diffuses from the alveoli (high O₂ concentration) into the blood (lower O₂ concentration) in the lungs" },
    { term: "Active Transport", definition: "The movement of molecules or ions across a cell membrane against a concentration gradient (from low to high concentration), using energy (ATP) from respiration. Requires carrier proteins embedded in the membrane. Unlike diffusion, it uses metabolic energy.", example: "Root hair cells use active transport to absorb mineral ions (e.g. nitrate) from the soil, even when ions are more concentrated inside the cell" },
    { term: "Pathogens", definition: "Microorganisms that cause infectious disease. The four types are: bacteria (e.g. Salmonella — food poisoning), viruses (e.g. influenza — flu), fungi (e.g. Tinea — athlete's foot), and protists (e.g. Plasmodium — malaria, spread by mosquito vectors). Each type has different structures and requires different treatments.", example: "Bacteria can be treated with antibiotics; viruses cannot — they require antiviral drugs or vaccination" },
    { term: "Antibodies", definition: "Proteins produced by lymphocytes (white blood cells) in response to a specific antigen on a pathogen. Antibodies have a shape complementary to the antigen. They neutralise pathogens (preventing entry to cells) or label them for destruction by phagocytes (agglutination). Memory lymphocytes remain after infection, enabling a faster response on re-exposure.", example: "After a measles infection, antibodies and memory cells persist — future exposure triggers rapid antibody production preventing illness" },
    { term: "Insulin and Glucagon", definition: "Hormones produced by the pancreas to regulate blood glucose. Insulin (from beta cells): released when blood glucose is high; causes liver and muscle cells to absorb glucose and convert it to glycogen (glycogenesis), lowering blood glucose. Glucagon (from alpha cells): released when blood glucose is low; causes the liver to convert glycogen back to glucose (glycogenolysis), raising blood glucose.", example: "After a meal, blood glucose rises → insulin released → glycogen stored. After exercise, blood glucose falls → glucagon released → glycogen broken down" },
    { term: "Food Chain and Energy Transfer", definition: "A food chain shows the flow of energy from producer (plants) through consumers. Energy is lost at each trophic level as heat (from respiration), movement, and undigested material. Typically only about 10% of energy is transferred between levels. This is why food chains rarely have more than four or five links.", example: "Grass → rabbit → fox. If grass has 10,000 kJ, the rabbit gets ~1,000 kJ, the fox ~100 kJ — 90% lost at each stage" },
    { term: "Reflex Arc", definition: "The pathway of a nerve impulse in a reflex action: stimulus → receptor → sensory neurone → relay neurone (in spinal cord) → motor neurone → effector (muscle or gland) → response. Reflexes are automatic, very fast, and do not require conscious thought. Synapses (gaps between neurones) transmit signals via neurotransmitter chemicals.", example: "Touching a hot object: heat receptor → sensory neurone → spinal cord relay → motor neurone → bicep muscle contracts, pulling hand away" },
    // Chemistry
    { term: "Activation Energy", definition: "The minimum energy that colliding particles must have for a reaction to occur. A catalyst works by providing an alternative reaction pathway with a lower activation energy, so a greater proportion of particles have sufficient energy to react. Shown on an energy profile diagram as the 'hill' between reactants and products.", example: "Enzymes are biological catalysts — they lower the activation energy of biochemical reactions in the body" },
    { term: "Alkanes and Alkenes", definition: "Alkanes: saturated hydrocarbons (only single C–C bonds). General formula CₙH₂ₙ₊₂. Examples: methane (CH₄), ethane (C₂H₆). Alkenes: unsaturated hydrocarbons with at least one C=C double bond. General formula CₙH₂ₙ. Examples: ethene (C₂H₄). Test: alkenes decolourise bromine water; alkanes do not.", example: "Ethene (C₂H₄) + bromine water → colourless product (addition reaction across the double bond); ethane does not react with bromine water" },
    { term: "Electrolysis", definition: "The decomposition of an ionic compound (in solution or molten) by an electric current. At the cathode (negative electrode): cations are reduced (gain electrons). At the anode (positive electrode): anions are oxidised (lose electrons). The electrolyte must be liquid or dissolved so ions can move freely to carry charge.", example: "Electrolysis of copper sulfate solution: copper deposits at the cathode (Cu²⁺ + 2e⁻ → Cu); oxygen is released at the anode" },
    { term: "Percentage Yield", definition: "A measure of how much product is actually made compared to the theoretical maximum. Formula: % yield = (actual yield / theoretical yield) × 100%. Always less than 100% due to: incomplete reactions, loss during transfer, reversible reactions not going to completion, or side reactions occurring.", example: "If theoretical yield of NaCl is 5.85 g but actual yield is 4.68 g: % yield = (4.68/5.85) × 100 = 80%" },
    { term: "Greenhouse Effect", definition: "Solar radiation (short-wave) passes through the atmosphere and warms Earth's surface. Earth emits infrared radiation (long-wave). Greenhouse gases (CO₂, methane, water vapour) absorb this infrared and re-emit it in all directions, trapping heat. Human activities are increasing greenhouse gas concentrations, enhancing the greenhouse effect and causing global warming.", example: "Since the industrial revolution, CO₂ levels have risen from ~280 ppm to over 420 ppm, correlating with rising global temperatures" },
    { term: "Fractional Distillation of Crude Oil", definition: "A process that separates crude oil (a mixture of hydrocarbons) based on differences in boiling point. The oil is heated; vapours rise up a fractionating column which is hotter at the bottom. Fractions condense at different levels: short-chain hydrocarbons (petrol, gases) near the top; long-chain ones (fuel oil, bitumen) near the bottom. Shorter chains have lower boiling points and are more flammable.", example: "Fractions from top to bottom: refinery gas, petrol, naphtha, kerosene (jet fuel), diesel, fuel oil, bitumen" },
    { term: "Neutralisation", definition: "A reaction between an acid and a base (or alkali) to form a salt and water. General equation: acid + base → salt + water. For acids reacting with metal carbonates: acid + metal carbonate → salt + water + carbon dioxide. The pH of the solution changes from acidic or alkaline to neutral (pH 7) when the exact amounts react.", example: "HCl + NaOH → NaCl + H₂O. Hydrochloric acid + sodium hydroxide → sodium chloride + water (neutralisation)" },
    // Physics
    { term: "Gravitational Potential Energy (GPE)", definition: "The energy stored in an object due to its position in a gravitational field. Formula: GPE = mgh, where m = mass (kg), g = gravitational field strength (10 N/kg on Earth), h = height (m). When an object falls, GPE converts to kinetic energy (ignoring air resistance).", example: "A 2 kg book on a shelf 1.5 m high: GPE = 2 × 10 × 1.5 = 30 J. When it falls, 30 J becomes kinetic energy at the moment of impact" },
    { term: "Kinetic Energy", definition: "The energy an object has due to its motion. Formula: KE = ½mv², where m = mass (kg) and v = velocity (m/s). KE increases with the square of speed — doubling speed quadruples KE. This is why braking distance increases much more rapidly than speed.", example: "A car of mass 1000 kg at 20 m/s: KE = ½ × 1000 × 400 = 200,000 J = 200 kJ" },
    { term: "Power (Electrical)", definition: "The rate of energy transfer. Formula: P = IV (power = current × voltage), or P = I²R, or P = V²/R. Unit: watt (W) or kilowatt (kW). The energy transferred = P × t. On electrical appliances, the power rating (e.g. 2000 W kettle) tells you how quickly it uses energy.", example: "A 1200 W hair dryer used for 5 minutes: energy = 1200 × 300 = 360,000 J = 360 kJ" },
    { term: "Radiation (Nuclear)", definition: "Three types emitted by unstable nuclei: Alpha (α) = helium nucleus (2p + 2n), most ionising, stopped by paper. Beta (β) = fast electron emitted from nucleus, stopped by aluminium. Gamma (γ) = high-energy electromagnetic wave, most penetrating, reduced by thick lead/concrete. All are ionising and can damage DNA.", example: "Smoke detectors use alpha radiation from Americium-241 — alpha is most ionising so triggers the detector, but its low penetration makes it safe in a housing" },
    { term: "Pressure in Gases", definition: "Gas pressure is caused by the collisions of gas molecules with the walls of the container. Increasing temperature increases the kinetic energy of molecules, increasing the frequency and force of collisions, so pressure increases. Decreasing volume (at constant temperature) increases the frequency of collisions, increasing pressure. P₁V₁ = P₂V₂ (Boyle's Law) at constant temperature.", example: "A car tyre: pumping in more air increases the number of molecules and collisions, increasing pressure" },
    { term: "Nuclear Fission and Fusion", definition: "Fission: a large unstable nucleus (e.g. uranium-235) splits into two smaller nuclei plus neutrons and energy. The neutrons can cause further fissions — a chain reaction. Used in nuclear power stations. Fusion: two small nuclei (e.g. hydrogen isotopes) join to form a larger nucleus, releasing large amounts of energy. Powers stars. Requires extremely high temperatures to overcome electrostatic repulsion.", example: "Nuclear power: U-235 + neutron → Ba-141 + Kr-92 + 3 neutrons + energy (fission chain reaction)" },
    { term: "Momentum", definition: "The product of an object's mass and velocity. Formula: p = mv. Unit: kg m/s. The law of conservation of momentum: in a closed system, the total momentum before a collision equals the total momentum after. Impulse = change in momentum = force × time.", example: "A 0.5 kg ball moving at 10 m/s has momentum = 0.5 × 10 = 5 kg m/s. If it hits a wall and stops, impulse = 5 kg m/s" },
    { term: "Efficiency", definition: "The fraction of the total input energy that is transferred usefully. Formula: efficiency = useful output energy / total input energy (can be expressed as a decimal or percentage). Always less than 1 (100%) because some energy is always dissipated as thermal energy due to friction or electrical resistance.", example: "A motor takes in 500 J and does 350 J of useful work: efficiency = 350/500 = 0.7 = 70%" },
    { term: "Ohm's Law", definition: "The current through a conductor is directly proportional to the potential difference across it, provided the temperature remains constant. Formula: V = IR (voltage = current × resistance). A component that obeys Ohm's Law is called an ohmic conductor — its resistance is constant. A filament lamp does not obey Ohm's Law (resistance increases as it heats up).", example: "A 12 V supply connected across a 4 Ω resistor: I = V/R = 12/4 = 3 A" },
    { term: "Stopping Distance", definition: "Total stopping distance = thinking distance + braking distance. Thinking distance depends on reaction time (affected by tiredness, alcohol, drugs, distractions). Braking distance depends on speed (doubles → 4× braking distance, since KE = ½mv²), road conditions, tyre condition, and brake quality.", example: "At 30 mph: stopping distance ≈ 23 m. At 60 mph (double speed): stopping distance ≈ 73 m (not double — much more than double due to KE ∝ v²)" },
    { term: "Acceleration", definition: "The rate of change of velocity. Formula: a = (v − u) / t, where v = final velocity, u = initial velocity, t = time (s). Units: m/s². Also: v² = u² + 2as. A negative acceleration (deceleration) means the object is slowing down. On a velocity-time graph, acceleration = gradient.", example: "A car increases from 10 m/s to 30 m/s in 5 s: a = (30−10)/5 = 4 m/s²" },
  ],
};
